import{_ as o,o as e,c as n,f as s,a as c}from"./app-v4ODCOL5.js";const a={},t=c(`<h2 id="第-8-章-css-基础与布局" tabindex="-1"><a class="header-anchor" href="#第-8-章-css-基础与布局" aria-hidden="true">#</a> 第 8 章 CSS 基础与布局</h2><h3 id="q1-说说标准盒模型和-ie-盒模型有什么区别" tabindex="-1"><a class="header-anchor" href="#q1-说说标准盒模型和-ie-盒模型有什么区别" aria-hidden="true">#</a> Q1 说说标准盒模型和 IE 盒模型有什么区别？</h3><p><strong>考察点</strong>：是否真的知道 <code>width</code> 指的是哪一段宽度，能不能把两种模型算清楚。答到&quot;content-box 与 border-box 的 width 包含范围不同&quot;就算过关。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：标准盒模型（content-box）的 <code>width</code> 只算内容区，IE 盒模型（border-box）的 <code>width</code> 包含内容 + <code>padding</code> + <code>border</code>。</p></blockquote><ol><li>标准盒模型（W3C Box Model）：元素占位宽 = <code>width</code> + 左右 <code>padding</code> + 左右 <code>border</code> + 左右 <code>margin</code>。写 <code>width:100px; padding:10px; border:1px</code>，内容区仍是 100px，实际占位 122px。</li><li>IE 盒模型（IE Box Model）：占位宽 = <code>width</code> + 左右 <code>margin</code>，<code>padding</code> 和 <code>border</code> 从 <code>width</code> 里向内挤。同样的声明实际占位 100px，内容区只剩 78px。</li><li>高度方向规则完全一致。CSS3 的 <code>box-sizing</code> 用来切换：<code>content-box</code> 是默认值（标准），<code>border-box</code> 是 IE 模型。</li><li>成因是历史遗留：IE6 及更早的怪异模式（quirks mode）默认用 border-box，现代浏览器统一以 content-box 为初始值。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>border-box</code> 下 <code>width</code> 小于 <code>padding + border</code> 会怎样？答：内容区被压到 0，不会出现负宽度，元素至少保留 padding + border 的尺寸。</li><li>陷阱：只说&quot;IE 盒模型是 IE 独有的&quot;就结束，漏掉&quot;怪异模式&quot;这个前提，会被追问触发条件。</li><li>陷阱：把 <code>margin</code> 算进模型里。两种模型的 <code>margin</code> 都在 <code>width</code> 之外，不参与 width 计算。</li></ul><h3 id="q2-box-sizing-怎么用-项目里你会怎么设" tabindex="-1"><a class="header-anchor" href="#q2-box-sizing-怎么用-项目里你会怎么设" aria-hidden="true">#</a> Q2 box-sizing 怎么用？项目里你会怎么设？</h3><p><strong>考察点</strong>：是否知道默认值、真实工程写法，以及 border-box 的好处与代价。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>box-sizing</code> 决定 <code>width</code> 是否包含 padding 和 border，工程上统一设为 <code>border-box</code>，让&quot;写多少就是多少&quot;。</p></blockquote><ol><li>取值只有两个：<code>content-box</code>（默认，标准盒模型）、<code>border-box</code>（<code>width</code> 含 padding + border）。还有一个 <code>inherit</code> 表示继承父级。</li><li><code>border-box</code> 的最大价值是加 <code>padding</code>、加 <code>border</code> 不会撑破已定宽度的栅格，百分比布局、<code>width:100%</code> 配合内边距时不再需要 <code>calc()</code> 反算。</li><li>推荐全局写法：<code>html</code> 设 <code>border-box</code>，其余元素用 <code>inherit</code> 继承，这样第三方组件里单独改 <code>box-sizing</code> 不会污染子树。</li></ol><div class="language-css line-numbers-mode" data-ext="css"><pre class="language-css"><code><span class="token selector">html</span> <span class="token punctuation">{</span> <span class="token property">box-sizing</span><span class="token punctuation">:</span> border-box<span class="token punctuation">;</span> <span class="token punctuation">}</span>
<span class="token selector">*, *::before, *::after</span> <span class="token punctuation">{</span> <span class="token property">box-sizing</span><span class="token punctuation">:</span> inherit<span class="token punctuation">;</span> <span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><ol start="4"><li>代价：<code>border-box</code> 下内容区会被 padding 挤小，做&quot;输入框加图标&quot;这类需要精确内容区尺寸的场景要重新核算，必要时局部改回 <code>content-box</code>。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么用 <code>inherit</code> 而不是 <code>* { box-sizing: border-box }</code>？答：用 <code>inherit</code> 后，某个组件把自身改成 <code>content-box</code>，它的子元素会跟着变，语义上更可控，也方便局部覆盖。</li><li>陷阱：说 <code>box-sizing</code> 会影响 <code>margin</code>。它只作用于 <code>width</code> / <code>height</code> 与 padding、border 的关系。</li><li>陷阱：忘记伪元素。<code>*</code> 选择器匹配不到 <code>::before</code> / <code>::after</code>，所以要单独列出。</li></ul><h3 id="q3-外边距合并-margin-collapse-有哪几种情况-怎么解决" tabindex="-1"><a class="header-anchor" href="#q3-外边距合并-margin-collapse-有哪几种情况-怎么解决" aria-hidden="true">#</a> Q3 外边距合并（margin collapse）有哪几种情况？怎么解决？</h3><p><strong>考察点</strong>：这是 CSS 布局的高频深挖题，考三种情形能否说全，以及解决手段是否落地。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：相邻的块级元素在垂直方向的 <code>margin</code> 会合并成一个（取较大值），分兄弟、父子、自身三种情形，破解办法是制造 BFC 或用 padding / border 隔断。</p></blockquote><ol><li>相邻兄弟合并：上下两个块级元素的 <code>margin-bottom</code> 与下一个的 <code>margin-top</code> 合并，最终间距按&quot;正正取大、负负取最负、正负相加&quot;得出。</li><li>父子合并：父元素没有上 <code>padding</code>、上 <code>border</code>，且没有 BFC / 没有 <code>overflow</code> 触发时，子元素的 <code>margin-top</code> 会&quot;穿透&quot;到父元素外面，表现为父元素整体下移。</li><li>自身合并：一个空元素同时有 <code>margin-top</code> 和 <code>margin-bottom</code> 且没内容、没 padding / border / 高度时，两个 margin 合并成一个。</li><li>破解手段：给父元素加 <code>padding</code> 或 <code>border</code>、<code>overflow: hidden</code>、<code>display: flow-root</code>、改成 flex / grid 容器（弹性与网格容器的子项不参与合并）。只有 <code>margin</code> 会合并，<code>padding</code> 不会；只有垂直方向会合并，水平方向不会；浮动元素和绝对定位元素不参与合并。</li></ol><div class="language-css line-numbers-mode" data-ext="css"><pre class="language-css"><code><span class="token selector">.parent</span> <span class="token punctuation">{</span> <span class="token property">display</span><span class="token punctuation">:</span> flow-root<span class="token punctuation">;</span> <span class="token punctuation">}</span> <span class="token comment">/* 最干净的方案：创建 BFC，无副作用 */</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>overflow: hidden</code> 和 <code>display: flow-root</code> 哪个更好？答：<code>flow-root</code> 专为创建 BFC 而设计，没有裁剪内容、不能与 <code>position: sticky</code> 共存等副作用，现代项目优先用它。</li><li>陷阱：说&quot;外边距合并就是取最大值&quot;，遇到负值时会被问穿。规则是：正正取大、负负取最负、正负相加。</li><li>陷阱：把水平方向的 margin 也算进来。左右相邻元素（如两个 <code>inline-block</code>）的 margin 不合并。</li></ul><h3 id="q4-什么是-bfc-触发条件和实际用途分别是什么" tabindex="-1"><a class="header-anchor" href="#q4-什么是-bfc-触发条件和实际用途分别是什么" aria-hidden="true">#</a> Q4 什么是 BFC？触发条件和实际用途分别是什么？</h3><p><strong>考察点</strong>：BFC 是布局题的核心概念，要求定义、触发方式、用途三段式答完整。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：块级格式化上下文（Block Formatting Context，BFC）是一块独立的块级渲染区域，内部布局与外部完全隔离，最常用的用途是清除浮动、阻止 margin 合并、实现两栏自适应不被浮动元素覆盖。</p></blockquote><ol><li>定义：BFC 是一个独立的渲染上下文，内部元素的布局不会影响外部，外部也不会影响内部；计算 BFC 高度时会把内部的浮动元素算进去（这就是能清浮动的原因）。</li><li>触发条件：根元素 <code>html</code>；<code>float</code> 不为 <code>none</code>；<code>position</code> 为 <code>absolute</code> 或 <code>fixed</code>；<code>display</code> 为 <code>inline-block</code> / <code>table-cell</code> / <code>table-caption</code> / <code>flow-root</code>；<code>overflow</code> 不为 <code>visible</code>；<code>contain</code> 为 <code>layout</code> / <code>paint</code> / <code>strict</code> / <code>content</code>；弹性/网格容器的子项（flex item 本身也是 BFC 容器）。</li><li>用途一，清除浮动：父元素高度塌陷时，给父元素加 <code>overflow: hidden</code> 或 <code>display: flow-root</code> 让它包住浮动子元素。</li><li>用途二，阻止外边距合并：父子 margin 穿透时给父元素创建 BFC，两个 margin 各自独立。</li><li>用途三，阻止元素被浮动元素覆盖：右侧元素创建 BFC 后不会与左侧浮动元素重叠，实现自适应两栏。另外还可以阻止元素被浮动遮挡导致文字环绕错位。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>display: flow-root</code> 和 <code>overflow: hidden</code> 建 BFC 有区别吗？答：都是 BFC，但 <code>overflow: hidden</code> 会裁剪溢出内容、影响 sticky 定位，<code>flow-root</code> 没有这些副作用，且是标准为这个目的引入的取值。</li><li>陷阱：把 BFC 说成&quot;清除浮动的属性&quot;。它不是属性，是一种布局上下文；<code>clear</code> 才是清浮动的声明。</li><li>陷阱：以为 <code>position: relative</code> 能触发 BFC。只有 <code>absolute</code> 和 <code>fixed</code> 可以。</li></ul><h3 id="q5-什么是-ifc-和行盒-line-box-高度由什么决定" tabindex="-1"><a class="header-anchor" href="#q5-什么是-ifc-和行盒-line-box-高度由什么决定" aria-hidden="true">#</a> Q5 什么是 IFC 和行盒（line box）？高度由什么决定？</h3><p><strong>考察点</strong>：考对行内布局模型的理解，是&quot;为什么 inline 元素撑不开父元素&quot;的根因。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：行内格式化上下文（Inline Formatting Context，IFC）是块容器内部为行内内容创建的行式排版环境，每行形成一个行盒，行盒高度由行内元素的 <code>line-height</code>、<code>vertical-align</code> 和 replacement 元素的高度共同决定。</p></blockquote><ol><li>形成条件：一个块容器里如果只有行内级内容（文字、<code>inline</code>、<code>inline-block</code>、<code>inline-table</code>），内部就形成 IFC；遇到浮动、绝对定位、块级盒子会被打断成多个 IFC。</li><li>行盒（line box）是这一行内容的&quot;包裹盒&quot;，它的高度不等于子元素高度之和，而是由所有行内盒在垂直方向上的最高点到最低点决定。</li><li>关键点：<code>line-height</code> 决定行内盒的高度贡献，<code>vertical-align</code> 决定它在行盒内的垂直位置，<code>font-size</code> 决定基线位置。所以父元素用了 <code>line-height</code> 后，即使子元素很小，行盒也不会缩到子元素那么小。</li><li>每个 IFC 里都有一个隐含的&quot;支柱（strut）&quot;盒子，高度等于父元素 <code>font-size</code> 与 <code>line-height</code>，它保证了行盒最小高度——这就是&quot;图片下面总有一条缝&quot;的原因之一。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么行内元素设了 <code>padding-top</code> 但父元素高度没变？答：行内元素垂直 <code>padding</code> 会绘制背景、参与视觉渲染，但不参与行盒高度计算，所以父元素高度不变。</li><li>陷阱：把行盒高度算成&quot;最高的行内元素高度&quot;。<code>vertical-align</code> 会让子元素上下错位，可能要按 <code>line-height</code> 的上下半边再外扩。</li><li>陷阱：认为 <code>inline-block</code> 与 <code>inline</code> 的行盒计算方式相同。<code>inline-block</code> 整体作为原子参与行盒，其高度计入，且基线取最后一行内容的基线。</li></ul><h3 id="q6-包含块-containing-block-的确定规则是什么" tabindex="-1"><a class="header-anchor" href="#q6-包含块-containing-block-的确定规则是什么" aria-hidden="true">#</a> Q6 包含块（containing block）的确定规则是什么？</h3><p><strong>考察点</strong>：定位与百分比计算的根基，能把 static / relative / absolute / fixed 四种参照说清就是加分项。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：包含块是元素尺寸和位置计算的参照矩形，<code>static</code> / <code>relative</code> 参照最近的块容器祖先的<strong>内容框</strong>，<code>absolute</code> 参照最近的非 <code>static</code> 祖先的<strong>内边距框</strong>，<code>fixed</code> 参照视口（有 <code>transform</code> 等属性的祖先会打破）。</p></blockquote><ol><li><code>static</code> 和 <code>relative</code>：包含块是最近的块级容器祖先的<strong>内容框（content box）</strong>，宽度的百分比就是按这个框算的。</li><li><code>absolute</code>：包含块是最近的 <code>position</code> 不为 <code>static</code> 的祖先的<strong>内边距框（padding box）</strong>，也就是说 <code>left: 0</code> 停在 padding 内侧边界，<code>padding</code> 会算进偏移的起点。</li><li><code>fixed</code>：正常情况下包含块是视口。但祖先一旦有 <code>transform</code>、<code>filter</code>、<code>perspective</code>、<code>will-change: transform</code>、<code>contain: paint</code> / <code>layout</code>、<code>backdrop-filter</code>，它会成为 fixed 元素的包含块，元素就跟着该祖先滚动了。</li><li>如果找不到符合条件的祖先，<code>absolute</code> 的包含块是初始包含块（initial containing block），大小等于视口。百分比的宽高参照包含块，<code>margin</code> / <code>padding</code> 的百分比都按包含块的<strong>宽度</strong>计算（上下也不例外）。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么给祖先加了 <code>transform: translateZ(0)</code> 之后 <code>position: fixed</code> 的弹窗不固定在屏幕上了？答：<code>transform</code> 使该祖先成为包含块，<code>fixed</code> 相对它定位，页面滚动时弹窗就跟着动了。</li><li>陷阱：说百分比 <code>padding-top</code> 按高度计算。上下 padding 的百分比同样按包含块宽度算，这是&quot;padding-top 撑 16:9 占位&quot;trick 的基础。</li><li>陷阱：忽略 <code>absolute</code> 元素如何确定包含块——自己若还有 <code>static</code> 子元素，这些子元素的包含块是绝对定位元素的 padding box。</li></ul><h3 id="q7-五种定位-position-分别怎么参照-各自的应用场景是什么" tabindex="-1"><a class="header-anchor" href="#q7-五种定位-position-分别怎么参照-各自的应用场景是什么" aria-hidden="true">#</a> Q7 五种定位（position）分别怎么参照？各自的应用场景是什么？</h3><p><strong>考察点</strong>：定位是最常用的布局手段，考对照关系与实际选型。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>static</code> 是默认文档流，<code>relative</code> 相对自身原位置偏移但占位不变，<code>absolute</code> 相对最近的非 static 祖先定位并脱离文档流，<code>fixed</code> 相对视口（或被 transform 的祖先），<code>sticky</code> 在滚动到阈值前是 relative、之后是 fixed。</p></blockquote><table><thead><tr><th>取值</th><th>是否脱离文档流</th><th>偏移参照</th><th>典型用途</th></tr></thead><tbody><tr><td><code>static</code></td><td>否</td><td>无偏移，<code>top</code> 等无效</td><td>默认排版</td></tr><tr><td><code>relative</code></td><td>否（原位置保留）</td><td>自身原来的位置</td><td>做绝对定位的父级、微调、提升层级</td></tr><tr><td><code>absolute</code></td><td>是</td><td>最近非 static 祖先的 padding box</td><td>角标、下拉菜单、遮罩、居中</td></tr><tr><td><code>fixed</code></td><td>是</td><td>视口（或 transform 祖先）</td><td>固定头部、回到顶部、弹窗</td></tr><tr><td><code>sticky</code></td><td>否（保留占位）</td><td>最近的滚动容器 + 阈值</td><td>吸顶导航、表头吸附、分组标题</td></tr></tbody></table><ol><li><code>relative</code> 的 <code>z-index</code> 会生效（因为创建了层叠上下文）——这是它除了当定位父级的第二大用途。</li><li><code>absolute</code> 的元素宽度会收缩为适应内容（shrink-to-fit），所以居中时通常要配合 <code>left/right</code> + <code>margin: auto</code> 或 <code>transform</code>。</li><li><code>sticky</code> 必须设置至少一个阈值（<code>top</code> / <code>left</code> / <code>right</code> / <code>bottom</code>）才会生效，并受最近的滚动祖先影响。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>relative</code> 元素偏移后原位置还在吗？答：在，布局空间按原位置保留，后续元素不会补位，只是视觉上移动。</li><li>陷阱：说 <code>absolute</code> 相对浏览器窗口定位。那是 <code>fixed</code>；<code>absolute</code> 只在找不到定位祖先时才退化为初始包含块。</li><li>陷阱：给父级写 <code>position: relative</code> 但忘了它会创建层叠上下文，导致子元素的 <code>z-index</code> 被&quot;关&quot;在父级层里出不来。</li></ul><h3 id="q8-position-sticky-不生效的常见原因有哪些" tabindex="-1"><a class="header-anchor" href="#q8-position-sticky-不生效的常见原因有哪些" aria-hidden="true">#</a> Q8 position: sticky 不生效的常见原因有哪些？</h3><p><strong>考察点</strong>：典型的&quot;用过但说不清&quot;的题，能列出 3 条以上具体原因才算过关。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>sticky</code> 失效基本都出自&quot;没设阈值&quot;和&quot;滚动容器不是你以为的那个&quot;，最常见的是祖先有 <code>overflow: hidden/auto</code>、祖先有 <code>transform</code>、或父元素高度不够。</p></blockquote><ol><li>没写阈值：只写 <code>position: sticky</code> 而不写 <code>top</code> / <code>left</code> / <code>right</code> / <code>bottom</code> 中的任意一个，元素不会粘。</li><li>滚动容器不对：任一祖先设置了 <code>overflow: hidden</code> / <code>auto</code> / <code>scroll</code>，吸附就相对这个祖先而不是视口；若这个祖先高度与内容相当、本身不滚动，元素看起来就&quot;没生效&quot;。</li><li>祖先有 <code>transform</code> / <code>filter</code> / <code>perspective</code> / <code>will-change</code> / <code>contain: paint</code>：会改变包含块，吸附行为随之异常。</li><li>父元素高度不足：sticky 只能在自己父元素的范围内活动，父元素高度等于元素自身高度时没有可粘空间；另外父级若是 flex / grid 容器且子项被 <code>align-items: stretch</code> 拉伸，元素高度会撑满，也没有粘的余地。</li><li>兼容与表头：老版本 Safari 需要 <code>-webkit-sticky</code>；<code>&lt;th&gt;</code> 或 <code>&lt;tr&gt;</code> 的 sticky 在部分浏览器需要设到 <code>th</code> 上并配 <code>border-collapse: separate</code>。</li></ol><div class="language-css line-numbers-mode" data-ext="css"><pre class="language-css"><code><span class="token comment">/* 前提检查清单：无 overflow 祖先、无 transform 祖先、父级足够高、有阈值 */</span>
<span class="token selector">.header</span> <span class="token punctuation">{</span> <span class="token property">position</span><span class="token punctuation">:</span> sticky<span class="token punctuation">;</span> <span class="token property">top</span><span class="token punctuation">:</span> 0<span class="token punctuation">;</span> <span class="token property">z-index</span><span class="token punctuation">:</span> 10<span class="token punctuation">;</span> <span class="token punctuation">}</span>
<span class="token selector">.wrap</span> <span class="token punctuation">{</span> <span class="token property">overflow</span><span class="token punctuation">:</span> visible<span class="token punctuation">;</span> <span class="token punctuation">}</span> <span class="token comment">/* 祖先不要裁剪 */</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么给祖先加了 <code>overflow: hidden</code> 就吸不住了？答：粘性定位的滚动容器变成了该祖先，它若不产生滚动，元素就没有滚动距离可以吸附。</li><li>陷阱：只答&quot;要注意兼容性&quot;，漏掉 <code>overflow</code> 祖先和 <code>transform</code> 祖先这两个最常见的真实原因。</li><li>陷阱：以为 <code>sticky</code> 会脱离文档流。它保留原占位，只是视觉偏移，等同于&quot;滚动到阈值前 relative、之后 fixed&quot;。</li></ul><h3 id="q9-什么是层叠上下文-z-index-在什么条件下才生效" tabindex="-1"><a class="header-anchor" href="#q9-什么是层叠上下文-z-index-在什么条件下才生效" aria-hidden="true">#</a> Q9 什么是层叠上下文？z-index 在什么条件下才生效？</h3><p><strong>考察点</strong>：z-index 失效是实际开发最常见的疑难问题，考的是&quot;为什么我的 z-index 不管用&quot;。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：层叠上下文（Stacking Context）是元素在 z 轴上独立排布的&quot;层级组&quot;，<code>z-index</code> 只对定位元素或自身已创建层叠上下文的元素生效，且子元素的层级永远出不了父级层叠上下文。</p></blockquote><ol><li>创建层叠上下文的条件：根元素；<code>position</code> 为 <code>absolute</code> / <code>relative</code> / <code>fixed</code> / <code>sticky</code> 且 <code>z-index</code> 不为 <code>auto</code>；<code>position: fixed</code> / <code>sticky</code>（现代浏览器总是创建）；<code>z-index</code> 不为 auto 的弹性、网格子项；<code>opacity</code> 小于 1；<code>transform</code> / <code>filter</code> / <code>perspective</code> / <code>clip-path</code> / <code>mix-blend-mode</code> / <code>isolation: isolate</code> / <code>backdrop-filter</code>；<code>will-change</code> 指定了上述属性；<code>contain: layout</code> / <code>paint</code> / <code>strict</code> / <code>content</code>。</li><li>z-index 生效条件：元素是定位元素（<code>position</code> 不为 <code>static</code>），或者是 flex / grid 子项，或者通过了上述其他方式创建了层叠上下文。<code>z-index</code> 的取值是整数，可以为负。</li><li>同一层叠上下文内的绘制顺序（从低到高）：背景和边框 → 负 <code>z-index</code> 的子级 → 块级盒子 → 浮动盒子 → 行内盒子与文字 → <code>z-index: 0</code> / <code>auto</code> 的定位元素 → 正 <code>z-index</code> 的子级。</li><li>关键限制：子元素的 <code>z-index</code> 再大，也不能盖过父级层叠上下文之外的兄弟层级。父级被别的层压住，子级就一起被压住——这是&quot;设了 9999 依然被遮住&quot;的根本原因。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么给元素设了 <code>z-index: 9999</code> 还是被弹窗遮住？答：它的某个祖先创建了层叠上下文，整个祖先层级的层级低于弹窗所在层，提升子元素无效，需要提升那个祖先的 <code>z-index</code> 或把元素挪出该祖先。</li><li>陷阱：认为 <code>z-index</code> 对所有元素都生效。非定位、非层叠上下文的普通块元素设 <code>z-index</code> 完全无效。</li><li>陷阱：忽略 <code>opacity: 0.99</code>、<code>transform: translate(0)</code>、<code>filter: blur(0)</code> 也会创建层叠上下文，这些&quot;看起来无关&quot;的样式常是层级错乱的元凶。</li></ul><h3 id="q10-浮动-float-是什么-为什么要清除浮动-clearfix-怎么写" tabindex="-1"><a class="header-anchor" href="#q10-浮动-float-是什么-为什么要清除浮动-clearfix-怎么写" aria-hidden="true">#</a> Q10 浮动（float）是什么？为什么要清除浮动？clearfix 怎么写？</h3><p><strong>考察点</strong>：浮动的原理与副作用，<code>clearfix</code> 是必须能默写的基础代码。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>float</code> 让元素脱离普通流、靠左或靠右排列并允许文字环绕，副作用是父元素高度塌陷，清除浮动最标准的做法是用伪元素 <code>clear: both</code>。</p></blockquote><ol><li>浮动元素脱离普通流（但仍属于 BFC 内部），块级盒子会忽略它，行内内容（文字、图片）则会环绕它，这就是浮动最初的设计目的。</li><li>副作用一：父元素高度塌陷，因为浮动子元素不参与父元素高度计算。副作用二：后续元素被浮动覆盖，需要 <code>clear</code> 或创建 BFC。</li><li><code>clear: left / right / both</code> 的含义是&quot;该元素的上外边沿不能与同侧的浮动元素相邻&quot;，所以它会被推到浮动元素下方。</li><li>标准 clearfix：给父元素加伪元素，在最后生成一个清除浮动的块级盒子。</li></ol><div class="language-css line-numbers-mode" data-ext="css"><pre class="language-css"><code><span class="token selector">.clearfix::after</span> <span class="token punctuation">{</span>
  <span class="token property">content</span><span class="token punctuation">:</span> <span class="token string">&quot;&quot;</span><span class="token punctuation">;</span>
  <span class="token property">display</span><span class="token punctuation">:</span> block<span class="token punctuation">;</span>
  <span class="token property">clear</span><span class="token punctuation">:</span> both<span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ol start="5"><li>现代替代方案：直接给父元素 <code>display: flow-root</code>，一行搞定且无副作用；Bootstrap 等库保留 clearfix 主要是兼容老代码。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>clear: both</code> 为什么要配合 <code>display: block</code>？答：伪元素默认是行内元素，行内元素不参与块级浮动清除的规则，必须转成块级盒子才有效。</li><li>陷阱：说&quot;浮动完全脱离文档流&quot;。它与绝对定位不同，仍占据 BFC 内的空间、会影响文字环绕，只是块级盒子视而不见。</li><li>陷阱：<code>clearfix</code> 写成 <code>overflow: hidden</code> 却忘了它会裁剪溢出内容（如下拉菜单、阴影），在组件里要慎用。</li></ul><h3 id="q11-display-的常用取值有什么区别-怎么选" tabindex="-1"><a class="header-anchor" href="#q11-display-的常用取值有什么区别-怎么选" aria-hidden="true">#</a> Q11 display 的常用取值有什么区别？怎么选？</h3><p><strong>考察点</strong>：display 是布局语法的基础，考对照理解而不是背属性名。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>display</code> 决定元素在文档流中的身份（块级 / 行内 / 弹性容器 / 网格容器 / 不渲染），选型上&quot;容器用 flex 或 grid、文字流用 inline、需要整行占位用 block&quot;。</p></blockquote><table><thead><tr><th>取值</th><th>是否独占一行</th><th>宽高</th><th>垂直 margin/padding</th><th>典型场景</th></tr></thead><tbody><tr><td><code>block</code></td><td>是</td><td><code>width</code> / <code>height</code> 生效</td><td>都生效</td><td>容器、段落、列表项</td></tr><tr><td><code>inline</code></td><td>否</td><td><code>width</code> / <code>height</code> 无效</td><td>垂直方向不影响行盒</td><td>文字、链接、强调</td></tr><tr><td><code>inline-block</code></td><td>否</td><td>都生效</td><td>都生效</td><td>图标按钮、需要并排又要设尺寸</td></tr><tr><td><code>flex</code></td><td>是（块级弹性容器）</td><td>都生效</td><td>都生效</td><td>一维排列、居中、等分</td></tr><tr><td><code>grid</code></td><td>是（块级网格容器）</td><td>都生效</td><td>都生效</td><td>二维布局、页面骨架</td></tr><tr><td><code>none</code></td><td>不渲染</td><td>—</td><td>—</td><td>隐藏且不占位</td></tr><tr><td><code>contents</code></td><td>自身盒子消失</td><td>—</td><td>—</td><td>只保留子元素参与父级布局</td></tr></tbody></table><ol><li><code>inline-flex</code> / <code>inline-grid</code> 是行内级的弹性 / 网格容器，可以和其他行内元素并排。</li><li><code>display: contents</code> 会&quot;消掉&quot;元素自身的盒子，让子元素直接参与上层的布局。注意它在部分浏览器上会让元素失去语义（无障碍树中消失），按钮、列表这类有语义的元素慎用。</li><li><code>display: none</code> 的元素不产生盒子，不参与布局、不可访问、<code>transition</code> 无效；要保留占位用 <code>visibility: hidden</code>，要做动画用 <code>opacity</code> + <code>pointer-events</code>。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>inline-block</code> 元素之间为什么有缝隙？答：行内级盒子之间会保留 HTML 里的空白字符，形成空白节点。解决：父元素 <code>font-size: 0</code>、给 HTML 去换行、或用 flex 布局。</li><li>陷阱：说 <code>visibility: hidden</code> 也会触发重排。它只是不绘制，占位与几何都不变，属于重绘；<code>display: none</code> 才会让元素退出渲染树并触发重排。</li><li>陷阱：忽略 <code>display: contents</code> 的无障碍副作用，面试官常顺着问&quot;那它和 <code>display: none</code> 的区别&quot;。</li></ul><h3 id="q12-行内元素-inline-的-padding-和-margin-表现如何" tabindex="-1"><a class="header-anchor" href="#q12-行内元素-inline-的-padding-和-margin-表现如何" aria-hidden="true">#</a> Q12 行内元素（inline）的 padding 和 margin 表现如何？</h3><p><strong>考察点</strong>：经典细节题，考&quot;为什么行内元素设了上下 padding 却撑不开父级&quot;。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：行内元素左右方向的 <code>padding</code> / <code>margin</code> 正常撑开水平空间，上下方向的 <code>padding</code> 会绘制背景但不改变行盒高度、上下 <code>margin</code> 完全不生效。</p></blockquote><ol><li>水平方向：<code>margin-left/right</code>、<code>padding-left/right</code> 都会推开相邻内容，参与行内布局计算。</li><li>垂直方向：<code>padding-top/bottom</code> 会扩展元素的背景绘制区域和边框，但不会让行盒变高，也不会推开上下相邻行，视觉上会与上一行/下一行重叠。</li><li>垂直方向：<code>margin-top/bottom</code> 对行内元素<strong>完全无效</strong>（不影响行盒高度，也不改变位置），设置后无任何视觉与布局效果。</li><li>想要上下 padding / margin 生效，把 <code>display</code> 改成 <code>inline-block</code>、<code>block</code> 或 <code>flex</code>。<code>inline-block</code> 整体作为原子参与行盒，宽高与四向 padding / margin 都正常。</li></ol><div class="language-css line-numbers-mode" data-ext="css"><pre class="language-css"><code><span class="token selector">.tag</span> <span class="token punctuation">{</span>
  <span class="token property">display</span><span class="token punctuation">:</span> inline-block<span class="token punctuation">;</span> <span class="token comment">/* 关键：让上下 padding 生效 */</span>
  <span class="token property">padding</span><span class="token punctuation">:</span> 2px 8px<span class="token punctuation">;</span>
  <span class="token property">margin</span><span class="token punctuation">:</span> 4px 0<span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么行内元素的上下 padding 会和别的行重叠？答：它的行盒高度只由 <code>line-height</code> 和 <code>vertical-align</code> 决定，padding 不参与，因此背景可以溢出到行盒之外。</li><li>陷阱：说&quot;行内元素不能设 padding&quot;。左右能设、上下能设但只影响绘制不影响布局，是&quot;生效一半&quot;。</li><li>陷阱：把这条规则套到 <code>inline-block</code> 上。<code>inline-block</code> 四向 padding / margin 都正常，它是行内级但内部是块级格式化。</li></ul><h3 id="q13-vertical-align-什么时候生效-基线对齐有哪些坑" tabindex="-1"><a class="header-anchor" href="#q13-vertical-align-什么时候生效-基线对齐有哪些坑" aria-hidden="true">#</a> Q13 vertical-align 什么时候生效？基线对齐有哪些坑？</h3><p><strong>考察点</strong>：图片底部缝隙、行内元素错位是后台系统里最常见的小 bug，考原理是否清楚。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>vertical-align</code> 只对行内级元素和表格单元格生效，它控制的是元素相对&quot;父元素基线&quot;或行盒的对齐方式，图片底部那条缝隙就是行盒基线与图片底边对齐造成的。</p></blockquote><ol><li>生效对象：<code>inline</code>、<code>inline-block</code>、<code>inline-table</code> 以及 <code>table-cell</code>。对块级元素无效；flex / grid 子项要用 <code>align-items</code> / <code>align-self</code> 控制。</li><li>常用取值：<code>baseline</code>（默认）、<code>top</code> / <code>middle</code> / <code>bottom</code>（相对行盒）、<code>text-top</code> / <code>text-bottom</code>（相对父元素文字）、<code>sub</code> / <code>super</code>、<code>&lt;length&gt;</code>（相对基线偏移）、<code>&lt;percentage&gt;</code>（相对 <code>line-height</code> 偏移，正值向上）。</li><li>基线的确定规则：行内元素取自己文字内容的基线；<code>inline-block</code> 若内部有行内内容，取最后一行内容的基线，若没有内容或 <code>overflow</code> 不为 <code>visible</code>，则取<strong>下外边距边缘</strong>作为基线。</li><li>图片底部缝隙的本质：<code>&lt;img&gt;</code> 默认 <code>vertical-align: baseline</code>，行盒在基线以下还要留出下行空隙（descent），这段空隙就是那条缝。解决办法：<code>display: block</code>（推荐）、<code>vertical-align: bottom/top/middle</code>、父元素 <code>line-height: 0</code> 或 <code>font-size: 0</code>。</li></ol><div class="language-css line-numbers-mode" data-ext="css"><pre class="language-css"><code><span class="token selector">img</span> <span class="token punctuation">{</span> <span class="token property">display</span><span class="token punctuation">:</span> block<span class="token punctuation">;</span> <span class="token punctuation">}</span> <span class="token comment">/* 一句话消除图片底部空隙，最省事 */</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么 <code>inline-block</code> 空元素会莫名奇妙跑到顶部？答：它没有行内内容，基线是下外边距边缘，与其他元素的文字基线对齐后视觉上就&quot;抬高&quot;了，加 <code>vertical-align: top</code> 或塞一个 <code>&amp;nbsp;</code> 可解决。</li><li>陷阱：以为 <code>vertical-align: middle</code> 就是&quot;垂直居中&quot;。它是把元素的中线与父元素基线加上小写字母 x 高度的一半对齐，不是父元素盒子的中线。</li><li>陷阱：用 <code>line-height</code> 去垂直居中多行文本，结果行高失控。多行文本要用 flex 或 <code>display: table-cell</code> + <code>vertical-align: middle</code>。</li></ul><h3 id="q14-line-height-写百分比、数值、长度有什么区别-继承怎么算" tabindex="-1"><a class="header-anchor" href="#q14-line-height-写百分比、数值、长度有什么区别-继承怎么算" aria-hidden="true">#</a> Q14 line-height 写百分比、数值、长度有什么区别？继承怎么算？</h3><p><strong>考察点</strong>：细腻的继承题，答案的差异只体现在子元素 <code>font-size</code> 不同的时候。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：无单位数值（如 <code>1.5</code>）被继承的是&quot;这个比例&quot;，子元素按自己的 <code>font-size</code> 重算；百分比和长度值被继承的是&quot;计算后的固定像素值&quot;，子元素字号变了行高也不变。</p></blockquote><ol><li>无单位数值：<code>line-height: 1.5</code>，最终行高 = 1.5 × 元素自身 <code>font-size</code>，是推荐写法。</li><li>百分比：<code>line-height: 150%</code>，先按父元素 <code>font-size</code> 算出像素值（父 16px → 24px），把 24px 这个计算值继承给子元素。</li><li>长度值：<code>line-height: 24px</code>，直接是绝对像素，子元素继承 24px。<code>em</code> 与百分比同理，属于计算后继承。</li><li>后果对比：父元素 16px / <code>150%</code> → 24px，子元素 <code>font-size: 32px</code> 时行高仍是 24px，文字会挤在一起；写成 <code>1.5</code> 则子元素行高自动变 48px。</li></ol><div class="language-css line-numbers-mode" data-ext="css"><pre class="language-css"><code><span class="token selector">body</span> <span class="token punctuation">{</span> <span class="token property">font-size</span><span class="token punctuation">:</span> 16px<span class="token punctuation">;</span> <span class="token property">line-height</span><span class="token punctuation">:</span> 1.5<span class="token punctuation">;</span> <span class="token punctuation">}</span>   <span class="token comment">/* 推荐：子元素自动重算 */</span>
<span class="token selector">.bad</span>  <span class="token punctuation">{</span> <span class="token property">font-size</span><span class="token punctuation">:</span> 16px<span class="token punctuation">;</span> <span class="token property">line-height</span><span class="token punctuation">:</span> 150%<span class="token punctuation">;</span> <span class="token punctuation">}</span> <span class="token comment">/* 子元素字号变化时行高不跟 */</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>line-height: 1</code> 和 <code>line-height: 0</code> 有什么区别？答：<code>1</code> 时行高等于字号，文字不重叠但很挤；<code>0</code> 时行高为 0，文字会严重重叠，只适合临时用 <code>font-size: 0</code> 消除空白节点。</li><li>陷阱：认为 <code>line-height: 150%</code> 和 <code>line-height: 1.5</code> 完全等价。只有在子元素字号与父级一致时才等价。</li><li>陷阱：用 <code>line-height</code> 等于父元素高度做垂直居中，遇到多行文本或字号不同的子元素就崩，现代项目直接用 flex 居中。</li></ul><h3 id="q15-flex-容器-弹性盒-有哪些属性-各控制什么方向" tabindex="-1"><a class="header-anchor" href="#q15-flex-容器-弹性盒-有哪些属性-各控制什么方向" aria-hidden="true">#</a> Q15 Flex 容器（弹性盒）有哪些属性？各控制什么方向？</h3><p><strong>考察点</strong>：Flexbox 是当下布局主力，先考容器属性，再考项目属性，比重很高。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：弹性盒（Flexible Box，Flexbox）容器属性按&quot;主轴方向、主轴对齐、交叉轴对齐、换行、间距&quot;五组记忆：<code>flex-direction</code> / <code>justify-content</code> / <code>align-items</code> 与 <code>align-content</code> / <code>flex-wrap</code> / <code>gap</code>。</p></blockquote><ol><li><code>flex-direction</code>：<code>row</code>（默认，主轴水平向右）、<code>row-reverse</code>、<code>column</code>、<code>column-reverse</code>。它决定主轴的起点和方向，其他所有属性都相对它解释。</li><li><code>flex-wrap</code>：<code>nowrap</code>（默认，不换行且项目会被压缩）、<code>wrap</code>（换行）、<code>wrap-reverse</code>。简写 <code>flex-flow: row wrap</code>。</li><li><code>justify-content</code>：主轴对齐。<code>flex-start</code>、<code>flex-end</code>、<code>center</code>、<code>space-between</code>、<code>space-around</code>、<code>space-evenly</code>。</li><li><code>align-items</code>：单行情况下交叉轴对齐。<code>stretch</code>（默认，未设尺寸时拉满）、<code>flex-start</code>、<code>flex-end</code>、<code>center</code>、<code>baseline</code>。</li><li><code>align-content</code>：<strong>多行</strong>时的交叉轴对齐（对单行无效，必须配合 <code>flex-wrap: wrap</code>）。取值同 <code>justify-content</code> 再加 <code>stretch</code>。</li><li><code>gap</code> / <code>row-gap</code> / <code>column-gap</code>：项目间距，取代过去用 <code>margin</code> 拼间距的写法，不会在最外侧多出间距。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>align-items</code> 和 <code>align-content</code> 有什么区别？答：<code>align-items</code> 管单行内每个项目在自己的行内怎么对齐；<code>align-content</code> 管多行之间整体怎么分布，不换行时它无效。</li><li>陷阱：把 <code>justify-content</code> 当成&quot;水平居中&quot;。它是主轴对齐，<code>flex-direction: column</code> 时它控制的是垂直方向。</li><li>陷阱：给容器设了 <code>align-items: stretch</code> 后子元素 <code>height</code> 不生效——<code>stretch</code> 只在子元素没有确定高度时才拉伸，想固定高度就写 <code>align-items: flex-start</code> 或给子元素设 <code>align-self: flex-start</code>。</li></ul><h3 id="q16-flex-grow、flex-shrink、flex-basis-分别是什么" tabindex="-1"><a class="header-anchor" href="#q16-flex-grow、flex-shrink、flex-basis-分别是什么" aria-hidden="true">#</a> Q16 flex-grow、flex-shrink、flex-basis 分别是什么？</h3><p><strong>考察点</strong>：三个项目属性的语义与计算差异，是 Flex 的进阶核心。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>flex-basis</code> 是项目在主轴上的初始尺寸，<code>flex-grow</code> 是分剩余空间的权重，<code>flex-shrink</code> 是空间不足时的收缩权重，三者分别管&quot;起点、放大、缩小&quot;。</p></blockquote><ol><li><code>flex-basis</code>：主轴初始尺寸，默认 <code>auto</code> 表示取项目的 <code>width</code> / <code>height</code>（若没设则取内容尺寸），设为 <code>0</code> 则初始尺寸为 0，长度值 / 百分比都支持，<code>content</code> 表示按内容尺寸。</li><li><code>flex-grow</code>：默认 <code>0</code>，即不放大。容器有剩余空间时，按各项目的 <code>grow</code> 值占比分配。两个项目 <code>grow</code> 为 1 和 2，剩余 300px 则分别得到 100px 和 200px。</li><li><code>flex-shrink</code>：默认 <code>1</code>，即空间不足时允许收缩。收缩量按 <code>shrink × flex-basis</code> 的加权比例分摊，不是单纯按 <code>shrink</code> 比例，这点常被问。</li><li>注意优先级：<code>flex-basis</code> 不为 <code>auto</code> 时，主轴尺寸优先按 <code>flex-basis</code>，<code>width</code> 会被忽略（交叉轴方向才看 <code>height</code>）。</li></ol><div class="language-css line-numbers-mode" data-ext="css"><pre class="language-css"><code><span class="token selector">.item-a</span> <span class="token punctuation">{</span> <span class="token property">flex-grow</span><span class="token punctuation">:</span> 1<span class="token punctuation">;</span> <span class="token property">flex-shrink</span><span class="token punctuation">:</span> 1<span class="token punctuation">;</span> <span class="token property">flex-basis</span><span class="token punctuation">:</span> 0<span class="token punctuation">;</span> <span class="token punctuation">}</span>   <span class="token comment">/* 等分 */</span>
<span class="token selector">.item-b</span> <span class="token punctuation">{</span> <span class="token property">flex-grow</span><span class="token punctuation">:</span> 0<span class="token punctuation">;</span> <span class="token property">flex-shrink</span><span class="token punctuation">:</span> 0<span class="token punctuation">;</span> <span class="token property">flex-basis</span><span class="token punctuation">:</span> 200px<span class="token punctuation">;</span> <span class="token punctuation">}</span> <span class="token comment">/* 固定不缩 */</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么设了 <code>flex-basis: 200px</code> 后 <code>width: 100px</code> 没用了？答：主轴方向上 <code>flex-basis</code> 优先级高于 <code>width</code>，<code>auto</code> 时才会回退到 <code>width</code>。</li><li>陷阱：认为 <code>flex-shrink</code> 是等比收缩。实际要乘以 <code>flex-basis</code>，<code>basis</code> 大的项目收缩得更多。</li><li>陷阱：以为 <code>flex-grow</code> 能处理&quot;内容超出容器&quot;的情况。空间为负时只有 <code>flex-shrink</code> 起作用，<code>grow</code> 完全不生效。</li></ul><h3 id="q17-flex-1-的完整含义是什么-为什么常要配-flex-basis-0" tabindex="-1"><a class="header-anchor" href="#q17-flex-1-的完整含义是什么-为什么常要配-flex-basis-0" aria-hidden="true">#</a> Q17 flex: 1 的完整含义是什么？为什么常要配 flex-basis: 0？</h3><p><strong>考察点</strong>：<code>flex: 1</code> 是最高频的写法之一，考简写展开与 <code>basis</code> 的影响。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>flex: 1</code> 等价于 <code>flex: 1 1 0%</code>（<code>grow: 1</code>、<code>shrink: 1</code>、<code>basis: 0%</code>），它让项目忽略自身内容宽度、从 0 开始等分剩余空间。</p></blockquote><ol><li>简写规则：<code>flex: &lt;grow&gt; &lt;shrink&gt; &lt;basis&gt;</code>。省略规则是 <code>flex: 1</code> → <code>1 1 0%</code>；<code>flex: auto</code> → <code>1 1 auto</code>；<code>flex: none</code> → <code>0 0 auto</code>；<code>flex: 0</code> → <code>0 1 0%</code>（注意不是 <code>0 0 0%</code>）。</li><li><code>flex-basis: 0%</code> 的作用：把主轴初始尺寸归零，所有项目站在同一起跑线，剩余空间严格按 <code>grow</code> 比例平分，从而实现&quot;宽度完全相等&quot;，不受内容多少影响。</li><li><code>flex: auto</code>（<code>basis: auto</code>）的差异：先按内容宽度占位，再把剩余空间按 <code>grow</code> 平分，所以内容多的项目更宽，做等分布局时会出现&quot;被文字撑歪&quot;的现象。</li><li>实践要点：<code>flex: 1</code> 配 <code>min-width: 0</code> 才能正确收缩到小于内容宽度，避免内部文字或代码块把容器撑破（见 Q18）。</li></ol><div class="language-css line-numbers-mode" data-ext="css"><pre class="language-css"><code><span class="token selector">.row</span> <span class="token punctuation">{</span> <span class="token property">display</span><span class="token punctuation">:</span> flex<span class="token punctuation">;</span> <span class="token punctuation">}</span>
<span class="token selector">.row &gt; *</span> <span class="token punctuation">{</span> <span class="token property">flex</span><span class="token punctuation">:</span> 1<span class="token punctuation">;</span> <span class="token property">min-width</span><span class="token punctuation">:</span> 0<span class="token punctuation">;</span> <span class="token punctuation">}</span> <span class="token comment">/* 严格等宽 + 允许被压缩 */</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>flex: 1</code> 和 <code>flex: auto</code> 什么时候结果一样？答：当所有项目内容尺寸相同、且都不触发收缩时结果一致；内容长度不同时结果不同。</li><li>陷阱：答 <code>flex: 1</code> 是 <code>1 1 auto</code>。这是最常见的错误，区别就在于 <code>basis</code> 是 <code>0%</code> 还是 <code>auto</code>。</li><li>陷阱：以为 <code>flex: 1</code> 就等于 <code>width</code> 均分。它还受 <code>min-width: auto</code> 和 <code>gap</code> 影响，容器有 <code>gap</code> 时要先扣掉间距再分。</li></ul><h3 id="q18-flex-布局里为什么内容会溢出-min-width-auto-是怎么回事" tabindex="-1"><a class="header-anchor" href="#q18-flex-布局里为什么内容会溢出-min-width-auto-是怎么回事" aria-hidden="true">#</a> Q18 Flex 布局里为什么内容会溢出？min-width: auto 是怎么回事？</h3><p><strong>考察点</strong>：真实业务里&quot;省略号失效 / 表格被撑破&quot;的根因，属于深挖题。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：弹性项目默认 <code>min-width: auto</code>，主轴方向上不允许缩小到自身内容的&quot;最小尺寸&quot;以下，所以里面的长文本会把容器撑开，必须显式写 <code>min-width: 0</code> 或 <code>overflow: hidden</code> 才能正常收缩。</p></blockquote><ol><li>原因：CSS 规范为弹性项目的 <code>min-width</code> 设了初始值 <code>auto</code>，含义是&quot;不小于内容的最小尺寸（min-content）&quot;。<code>flex-shrink: 1</code> 想收缩，但被这个下限挡住了。</li><li>表现：单行文本省略号不生效、右侧内容把左侧挤没、长英文单词或 <code>&lt;pre&gt;</code> 撑破弹窗宽度、表格列宽失控。</li><li>解决：给需要收缩的项目加 <code>min-width: 0</code>（主轴为 <code>column</code> 时是 <code>min-height: 0</code>），或加 <code>overflow: hidden</code> / <code>overflow: auto</code> / <code>text-overflow: ellipsis</code> 配合 <code>white-space: nowrap</code>。</li><li>让省略号真正生效的三件套：父级项目 <code>min-width: 0</code>，文本元素自身 <code>overflow: hidden; white-space: nowrap; text-overflow: ellipsis</code>。</li></ol><div class="language-css line-numbers-mode" data-ext="css"><pre class="language-css"><code><span class="token selector">.flex-item</span> <span class="token punctuation">{</span> <span class="token property">flex</span><span class="token punctuation">:</span> 1<span class="token punctuation">;</span> <span class="token property">min-width</span><span class="token punctuation">:</span> 0<span class="token punctuation">;</span> <span class="token punctuation">}</span>      <span class="token comment">/* 关键一行 */</span>
<span class="token selector">.ellipsis</span> <span class="token punctuation">{</span> <span class="token property">overflow</span><span class="token punctuation">:</span> hidden<span class="token punctuation">;</span> <span class="token property">white-space</span><span class="token punctuation">:</span> nowrap<span class="token punctuation">;</span> <span class="token property">text-overflow</span><span class="token punctuation">:</span> ellipsis<span class="token punctuation">;</span> <span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么只给文本元素加 <code>overflow: hidden</code> 有时还不行？答：如果文本元素外面的弹性项目没解除 <code>min-width: auto</code>，撑宽的仍是外层项目，必须在外层解除。</li><li>陷阱：把 <code>min-width: auto</code> 说成&quot;所有元素都这样&quot;。普通块级元素 <code>min-width</code> 初始值是 <code>0</code>，只有弹性/网格项目才是 <code>auto</code>。</li><li>陷阱：用 <code>flex-shrink: 0</code> 去解决溢出。那反而会让项目完全不收缩，溢出更严重。</li></ul><h3 id="q19-grid-的核心属性怎么用-auto-fit-和-auto-fill-有什么区别" tabindex="-1"><a class="header-anchor" href="#q19-grid-的核心属性怎么用-auto-fit-和-auto-fill-有什么区别" aria-hidden="true">#</a> Q19 Grid 的核心属性怎么用？auto-fit 和 auto-fill 有什么区别？</h3><p><strong>考察点</strong>：网格（Grid）是现代布局的另一半，考核心 API 与两个容易混的取值。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>grid-template-columns</code> 用 <code>repeat()</code> + <code>minmax()</code> + <code>fr</code> 定义列轨道，<code>auto-fit</code> 会折叠空轨道让卡片拉伸铺满，<code>auto-fill</code> 会保留空轨道让卡片保持固定宽度。</p></blockquote><ol><li><code>fr</code> 是网格容器剩余空间的分配单位，<code>1fr 2fr</code> 表示按 1:2 分配；注意 <code>fr</code> 的最小值是 <code>auto</code>，内容过长时同样会溢出，需要 <code>minmax(0, 1fr)</code> 兜底。</li><li><code>minmax(min, max)</code> 定义轨道的尺寸范围，常与 <code>repeat()</code> 组合做响应式卡片墙，不用写媒体查询。</li><li><code>auto-fit</code> 与 <code>auto-fill</code> 都用于&quot;尽可能多地排列固定宽度轨道&quot;。区别只在有空余空间时：<code>auto-fill</code> 保留空轨道（卡片维持 <code>minmax</code> 的最小宽度），<code>auto-fit</code> 把空轨道折叠为 0，剩下的轨道被拉伸铺满整行。</li><li>另外两个常用函数：<code>repeat(3, 1fr)</code> 固定列数；<code>grid-auto-rows</code> / <code>grid-auto-flow</code> 控制隐式轨道与自动排列。</li></ol><div class="language-css line-numbers-mode" data-ext="css"><pre class="language-css"><code><span class="token selector">.cards</span> <span class="token punctuation">{</span> <span class="token property">display</span><span class="token punctuation">:</span> grid<span class="token punctuation">;</span> <span class="token property">gap</span><span class="token punctuation">:</span> 16px<span class="token punctuation">;</span>
  <span class="token property">grid-template-columns</span><span class="token punctuation">:</span> <span class="token function">repeat</span><span class="token punctuation">(</span>auto-fit<span class="token punctuation">,</span> <span class="token function">minmax</span><span class="token punctuation">(</span>200px<span class="token punctuation">,</span> 1fr<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
<span class="token comment">/* 需要卡片宽度固定、剩余空间留白时，把 auto-fit 换成 auto-fill */</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：只有 3 张卡片时，<code>auto-fit</code> 和 <code>auto-fill</code> 显示有什么不同？答：容器够宽时 <code>auto-fit</code> 会把 3 张卡片拉伸到整行宽，<code>auto-fill</code> 则保持 <code>minmax</code> 的宽度并在右侧留白。</li><li>陷阱：说 <code>fr</code> 一定是等分。它分配的是扣掉内容与 <code>gap</code> 之后的剩余空间，且默认最小尺寸为 <code>auto</code>。</li><li>陷阱：忘了 <code>gap</code> 会占掉宽度，用 <code>repeat(3, 1fr)</code> 加 <code>gap</code> 时不需要再手动减宽度，Grid 会自动算。</li></ul><h3 id="q20-怎么用-grid-area-和命名区域做页面布局" tabindex="-1"><a class="header-anchor" href="#q20-怎么用-grid-area-和命名区域做页面布局" aria-hidden="true">#</a> Q20 怎么用 grid-area 和命名区域做页面布局？</h3><p><strong>考察点</strong>：网格的真正优势在于区域命名，能写出可读的骨架代码是加分项。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：用 <code>grid-template-areas</code> 画出布局草图、给子元素用 <code>grid-area</code> 指名占位，是最可读的页面骨架写法；同时 <code>grid-area</code> 也是 <code>row-start / column-start / row-end / column-end</code> 的简写。</p></blockquote><ol><li><code>grid-template-areas</code> 里同一名字必须构成矩形，否则声明整体失效；用 <code>.</code> 表示空单元格。</li><li>子元素通过 <code>grid-area: 名字</code> 落到对应区域，不需要计算行列号，改布局只改草图文案，非常适合改版频繁的中后台。</li><li><code>grid-area</code> 的另一种用法是四值简写：<code>grid-area: 1 / 2 / 3 / 4</code> 表示行起、列起、行止、列止，可用于跨行跨列。</li><li>实际项目里常见组合是&quot;外层 Grid 画大区块，内层 Flex 排组件内部&quot;，既直观又灵活。</li></ol><div class="language-css line-numbers-mode" data-ext="css"><pre class="language-css"><code><span class="token selector">.layout</span> <span class="token punctuation">{</span> <span class="token property">display</span><span class="token punctuation">:</span> grid<span class="token punctuation">;</span> <span class="token property">gap</span><span class="token punctuation">:</span> 12px<span class="token punctuation">;</span> <span class="token property">height</span><span class="token punctuation">:</span> 100vh<span class="token punctuation">;</span>
  <span class="token property">grid-template-columns</span><span class="token punctuation">:</span> 200px 1fr<span class="token punctuation">;</span>
  <span class="token property">grid-template-rows</span><span class="token punctuation">:</span> 56px 1fr<span class="token punctuation">;</span>
  <span class="token property">grid-template-areas</span><span class="token punctuation">:</span> <span class="token string">&quot;header header&quot;</span> <span class="token string">&quot;aside main&quot;</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
<span class="token selector">.header</span> <span class="token punctuation">{</span> <span class="token property">grid-area</span><span class="token punctuation">:</span> header<span class="token punctuation">;</span> <span class="token punctuation">}</span>
<span class="token selector">.aside</span>  <span class="token punctuation">{</span> <span class="token property">grid-area</span><span class="token punctuation">:</span> aside<span class="token punctuation">;</span> <span class="token punctuation">}</span>
<span class="token selector">.main</span>   <span class="token punctuation">{</span> <span class="token property">grid-area</span><span class="token punctuation">:</span> main<span class="token punctuation">;</span> <span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：命名区域能用媒体查询改吗？答：可以，在媒体查询里重新声明 <code>grid-template-areas</code> 即可，子元素无需改动，这是它比 <code>float</code> 方案更好的地方。</li><li>陷阱：区域名写成非矩形（如 L 形），浏览器会丢弃整条 <code>grid-template-areas</code> 声明，布局退回默认，排查时优先怀疑这里。</li><li>陷阱：忘记给子元素设 <code>grid-area</code> 却以为会按顺序自动落入命名区域。自动排列只按源顺序填充，与命名区域无关。</li></ul><h3 id="q21-flex-和-grid-该怎么选" tabindex="-1"><a class="header-anchor" href="#q21-flex-和-grid-该怎么选" aria-hidden="true">#</a> Q21 Flex 和 Grid 该怎么选？</h3><p><strong>考察点</strong>：考选型判断力，面试官想听的是取舍依据，不是&quot;都能用&quot;。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：一维排列、内容驱动、需要按内容分配空间用 Flex；二维布局、结构驱动、需要行列同时对齐用 Grid。二者不是替代关系，通常外层 Grid 搭骨架、内层 Flex 排内容。</p></blockquote><ol><li>维度：Flex 一次只管一个方向（主轴），适合导航栏、按钮组、表单行、卡片内部；Grid 同时控制行和列，适合页面骨架、仪表盘、画廊、表格式布局。</li><li>驱动方式：Flex 是&quot;内容驱动&quot;，空间按内容与 <code>grow</code> / <code>shrink</code> 分配，内容变化时布局跟着变；Grid 是&quot;布局驱动&quot;，先定义轨道再往里放内容，更适合稳定结构。</li><li>能力差异：Grid 独有区域命名、轨道跨行跨列、<code>minmax</code> / <code>auto-fit</code> 响应式轨道；Flex 独有按内容比例伸缩、<code>order</code> 排序、单行基线对齐。</li><li>兼容与心智成本：两者现在都可用，Grid 在部分老旧移动端浏览器上支持略晚，<code>gap</code> 在 Flex 中支持也较晚（见 Q41），若需兼容极老设备，Grid 用在骨架、Flex 兜底更稳。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：一个容器可以是 Grid 又是 Flex 吗？答：同一元素只能选一种 <code>display</code>，但可以在别的元素上切换，也可以 <code>display: grid</code> 的容器内放 <code>display: flex</code> 的子元素。</li><li>陷阱：答&quot;Grid 完全可以替代 Flex&quot;。Flex 的内容驱动与自动分配在组件内部排列上更自然，Grid 写起来反而更啰嗦。</li><li>陷阱：忽略 <code>gap</code> 与旧浏览器兼容的取舍，只谈语法不谈降级，会被追问落地细节。</li></ul><h3 id="q22-水平垂直居中你有哪些方案-至少说出-6-种" tabindex="-1"><a class="header-anchor" href="#q22-水平垂直居中你有哪些方案-至少说出-6-种" aria-hidden="true">#</a> Q22 水平垂直居中你有哪些方案？（至少说出 6 种）</h3><p><strong>考察点</strong>：超高频题，考方案的广度与&quot;什么场景用哪种&quot;的判断。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：现代项目首选 Flex 或 Grid 的 <code>place-items: center</code>，需要不影响兄弟元素时用绝对定位 + <code>transform</code> 或 <code>margin: auto</code>，单行文本用 <code>line-height</code>。</p></blockquote><ol><li>Flex 方案：容器 <code>display: flex; justify-content: center; align-items: center</code>，最通用，无需知道子元素尺寸。</li><li>Grid 方案：容器 <code>display: grid; place-items: center</code>，两行搞定，子元素数量不限。</li><li>绝对定位 + <code>transform</code>：<code>position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%)</code>，不需要知道自身尺寸，缺点是 <code>transform</code> 会创建层叠上下文、影响子元素 fixed。</li><li>绝对定位 + <code>margin: auto</code>：四边偏移为 0，<code>margin: auto</code> 自动均分剩余空间，要求元素有确定宽高（或 <code>max-width</code> 配合 <code>width: 0</code> 之类的技巧），不影响子元素定位参照。</li><li><code>line-height</code> + <code>text-align: center</code>：只适合单行文本，<code>line-height</code> 等于容器高度。</li><li><code>display: table-cell</code> + <code>vertical-align: middle</code>：兼容性极好，适合老项目，代价是要多套一层且 <code>margin</code> 不生效。</li></ol><div class="language-css line-numbers-mode" data-ext="css"><pre class="language-css"><code><span class="token selector">.a</span> <span class="token punctuation">{</span> <span class="token property">display</span><span class="token punctuation">:</span> flex<span class="token punctuation">;</span> <span class="token property">justify-content</span><span class="token punctuation">:</span> center<span class="token punctuation">;</span> <span class="token property">align-items</span><span class="token punctuation">:</span> center<span class="token punctuation">;</span> <span class="token punctuation">}</span>
<span class="token selector">.b</span> <span class="token punctuation">{</span> <span class="token property">display</span><span class="token punctuation">:</span> grid<span class="token punctuation">;</span> <span class="token property">place-items</span><span class="token punctuation">:</span> center<span class="token punctuation">;</span> <span class="token punctuation">}</span>
<span class="token selector">.c</span> <span class="token punctuation">{</span> <span class="token property">position</span><span class="token punctuation">:</span> absolute<span class="token punctuation">;</span> <span class="token property">inset</span><span class="token punctuation">:</span> 0<span class="token punctuation">;</span> <span class="token property">margin</span><span class="token punctuation">:</span> auto<span class="token punctuation">;</span> <span class="token property">width</span><span class="token punctuation">:</span> 200px<span class="token punctuation">;</span> <span class="token property">height</span><span class="token punctuation">:</span> 120px<span class="token punctuation">;</span> <span class="token punctuation">}</span>
<span class="token selector">.d</span> <span class="token punctuation">{</span> <span class="token property">position</span><span class="token punctuation">:</span> absolute<span class="token punctuation">;</span> <span class="token property">top</span><span class="token punctuation">:</span> 50%<span class="token punctuation">;</span> <span class="token property">left</span><span class="token punctuation">:</span> 50%<span class="token punctuation">;</span> <span class="token property">transform</span><span class="token punctuation">:</span> <span class="token function">translate</span><span class="token punctuation">(</span>-50%<span class="token punctuation">,</span> -50%<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
<span class="token selector">.e</span> <span class="token punctuation">{</span> <span class="token property">text-align</span><span class="token punctuation">:</span> center<span class="token punctuation">;</span> <span class="token property">line-height</span><span class="token punctuation">:</span> 60px<span class="token punctuation">;</span> <span class="token punctuation">}</span>
<span class="token selector">.f</span> <span class="token punctuation">{</span> <span class="token property">display</span><span class="token punctuation">:</span> table-cell<span class="token punctuation">;</span> <span class="token property">vertical-align</span><span class="token punctuation">:</span> middle<span class="token punctuation">;</span> <span class="token property">text-align</span><span class="token punctuation">:</span> center<span class="token punctuation">;</span> <span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：绝对定位 + <code>margin: auto</code> 为什么能居中？答：<code>top/right/bottom/left</code> 都为 0 时元素尺寸被约束，<code>margin: auto</code> 把水平与垂直方向的剩余空间平分（见 Q27）。</li><li>陷阱：<code>translate(-50%, -50%)</code> 中的百分比是相对元素<strong>自身</strong>尺寸，不是父容器，说反了会被立刻纠正。</li><li>陷阱：用 <code>line-height</code> 给多行文本居中，结果行距被撑大；多行必须换 flex、grid 或 <code>table-cell</code>。</li></ul><h3 id="q23-怎么实现两栏布局-左侧固定、右侧自适应" tabindex="-1"><a class="header-anchor" href="#q23-怎么实现两栏布局-左侧固定、右侧自适应" aria-hidden="true">#</a> Q23 怎么实现两栏布局（左侧固定、右侧自适应）？</h3><p><strong>考察点</strong>：基础布局手写题，考多种实现与各自的坑。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：现代写法直接用 Flex（左固定宽、右 <code>flex: 1</code>）或 Grid（<code>grid-template-columns: 200px 1fr</code>），老方案用 <code>float</code> 或绝对定位。</p></blockquote><ol><li>Flex 方案：父容器 <code>display: flex</code>，左侧 <code>width: 200px; flex-shrink: 0</code>，右侧 <code>flex: 1; min-width: 0</code>。注意右侧内容宽时必须有 <code>min-width: 0</code>，否则溢出。</li><li>Grid 方案：<code>display: grid; grid-template-columns: 200px 1fr</code>，最简洁，右侧自动填满剩余空间。</li><li>浮动方案：左侧 <code>float: left; width: 200px</code>，右侧 <code>margin-left: 200px</code>（不是 <code>float: right</code>，否则右侧内容宽度计算会出问题），父元素需清浮动。</li><li>绝对定位方案：左侧 <code>position: absolute; width: 200px</code>，右侧 <code>margin-left: 200px</code>。适合侧栏需要脱离文档流做动画的场景，代价是父元素高度不撑开。</li></ol><div class="language-css line-numbers-mode" data-ext="css"><pre class="language-css"><code><span class="token selector">.layout</span> <span class="token punctuation">{</span> <span class="token property">display</span><span class="token punctuation">:</span> grid<span class="token punctuation">;</span> <span class="token property">grid-template-columns</span><span class="token punctuation">:</span> 200px 1fr<span class="token punctuation">;</span> <span class="token property">gap</span><span class="token punctuation">:</span> 16px<span class="token punctuation">;</span> <span class="token punctuation">}</span>
<span class="token comment">/* Flex 等价写法 */</span>
<span class="token selector">.layout-flex</span> <span class="token punctuation">{</span> <span class="token property">display</span><span class="token punctuation">:</span> flex<span class="token punctuation">;</span> <span class="token punctuation">}</span>
<span class="token selector">.layout-flex .aside</span> <span class="token punctuation">{</span> <span class="token property">width</span><span class="token punctuation">:</span> 200px<span class="token punctuation">;</span> <span class="token property">flex-shrink</span><span class="token punctuation">:</span> 0<span class="token punctuation">;</span> <span class="token punctuation">}</span>
<span class="token selector">.layout-flex .main</span>  <span class="token punctuation">{</span> <span class="token property">flex</span><span class="token punctuation">:</span> 1<span class="token punctuation">;</span> <span class="token property">min-width</span><span class="token punctuation">:</span> 0<span class="token punctuation">;</span> <span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：左侧固定宽用什么单位？答：侧栏常固定像素；如果需要跟随根字号做无障碍缩放，用 <code>rem</code>；<code>vw</code> 在移动端地址栏变化时会有抖动。</li><li>陷阱：右侧用 <code>float: right</code> 做成两栏，结果内容会环绕浮动元素、高度不一致，是新手典型错误。</li><li>陷阱：忘记 <code>flex-shrink: 0</code>，左侧在窄屏下被压扁，出现&quot;侧栏越缩越窄&quot;的问题。</li></ul><h3 id="q24-三栏布局、圣杯布局和双飞翼布局的区别是什么" tabindex="-1"><a class="header-anchor" href="#q24-三栏布局、圣杯布局和双飞翼布局的区别是什么" aria-hidden="true">#</a> Q24 三栏布局、圣杯布局和双飞翼布局的区别是什么？</h3><p><strong>考察点</strong>：经典布局手写题，考&quot;主内容优先渲染&quot;的实现技巧，属于进阶。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：三栏布局是左右固定、中间自适应；圣杯与双飞翼都是为了&quot;HTML 里中间主内容写在最前面（优先渲染 + SEO）&quot;，用负 <code>margin</code> 把两侧栏拉到同一行，区别在于解决中间内容被遮挡的方式。</p></blockquote><ol><li>相同点：都是左右固定宽、中间自适应；都把中间内容放在 DOM 最前，保证主内容优先加载与解析。</li><li>圣杯布局：父元素设左右 <code>padding</code> 为两侧宽度，三个子元素全部 <code>float: left</code>，中间 <code>width: 100%</code>，左侧 <code>margin-left: -100%</code>，右侧 <code>margin-left: -自身宽度</code>，最后用 <code>position: relative</code> 把左右两栏移到 padding 区域。</li><li>双飞翼布局：父元素不设 <code>padding</code>，中间是一个&quot;外壳&quot;盒子并设置左右 <code>margin</code> 给两侧让位，负 <code>margin</code> 逻辑相同，用 <code>margin</code> 代替了 <code>relative</code> 定位，少了一层定位计算。</li><li>现代写法：Flex（中间 <code>flex: 1</code> 放在最前，用 <code>order</code> 控制左右顺序）或 Grid 命名区域，几行代码即可，且天然等高。</li></ol><div class="language-css line-numbers-mode" data-ext="css"><pre class="language-css"><code><span class="token comment">/* 双飞翼核心：负 margin 把侧栏拉到主内容左侧 */</span>
<span class="token selector">.main</span>  <span class="token punctuation">{</span> <span class="token property">float</span><span class="token punctuation">:</span> left<span class="token punctuation">;</span> <span class="token property">width</span><span class="token punctuation">:</span> 100%<span class="token punctuation">;</span> <span class="token punctuation">}</span>          <span class="token comment">/* 外壳 */</span>
<span class="token selector">.main-inner</span> <span class="token punctuation">{</span> <span class="token property">margin</span><span class="token punctuation">:</span> 0 200px<span class="token punctuation">;</span> <span class="token punctuation">}</span>              <span class="token comment">/* 给两侧让位 */</span>
<span class="token selector">.left</span>  <span class="token punctuation">{</span> <span class="token property">float</span><span class="token punctuation">:</span> left<span class="token punctuation">;</span> <span class="token property">width</span><span class="token punctuation">:</span> 200px<span class="token punctuation">;</span> <span class="token property">margin-left</span><span class="token punctuation">:</span> -100%<span class="token punctuation">;</span> <span class="token punctuation">}</span>
<span class="token selector">.right</span> <span class="token punctuation">{</span> <span class="token property">float</span><span class="token punctuation">:</span> left<span class="token punctuation">;</span> <span class="token property">width</span><span class="token punctuation">:</span> 200px<span class="token punctuation">;</span> <span class="token property">margin-left</span><span class="token punctuation">:</span> -200px<span class="token punctuation">;</span> <span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么两侧栏要用负 <code>margin</code>？答：三栏都是 <code>float: left</code> 且中间占满 100% 宽，侧栏会被挤到下一行，负 <code>margin</code> 把它们&quot;拽&quot;回上一行的空白位置。</li><li>陷阱：把双飞翼和圣杯的实现混着说。核心区别是&quot;给中间让位的方式&quot;：圣杯用父 <code>padding</code> + <code>relative</code>，双飞翼用中间内层 <code>margin</code>。</li><li>陷阱：忘记负 <code>margin</code> 的上限，写错数值导致侧栏压住主内容，排查时先看 <code>margin-left</code> 的百分比/像素是否等于对应宽度。</li></ul><h3 id="q25-等高布局怎么做" tabindex="-1"><a class="header-anchor" href="#q25-等高布局怎么做" aria-hidden="true">#</a> Q25 等高布局怎么做？</h3><p><strong>考察点</strong>：真实业务里&quot;两栏背景不等高&quot;很常见，考方案的演进与取舍。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：现代直接用 Flex（默认 <code>align-items: stretch</code>）或 Grid（轨道内子项默认拉伸）就能等高，老项目用 <code>table-cell</code> 或&quot;大 <code>padding</code> + 负 <code>margin</code>&quot;技巧。</p></blockquote><ol><li>Flex 方案：容器 <code>display: flex</code>，子项不写 <code>align-items</code> 时默认 <code>stretch</code>，各列自动拉伸到最高列的高度，最适合两栏背景需要齐平的场景。</li><li>Grid 方案：同一行轨道内的子项默认撑满轨道高度，<code>align-items: stretch</code> 也是默认值，天然等高。</li><li><code>display: table</code> / <code>table-cell</code> 方案：把父元素设为 <code>display: table</code>，子元素 <code>display: table-cell; vertical-align: top</code>，兼容性好，代价是无法使用 <code>margin</code>、结构受表格语义影响、响应式折叠要额外处理。</li><li>经典 hack：给每列 <code>padding-bottom: 9999px; margin-bottom: -9999px</code>，再用父元素 <code>overflow: hidden</code> 裁掉多余部分。能实现等高背景，但容易影响内部定位与滚动，现代项目不建议再用。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：Flex 等高后子元素里的内容怎么不跟着拉伸？答：给子元素设置 <code>align-self: flex-start</code> 或显式高度，只让背景容器等高。</li><li>陷阱：用 <code>height: 100%</code> 做等高。百分比高度依赖父元素确定高度，父级 <code>height: auto</code> 时直接失效（见 Q44）。</li><li>陷阱：负 <code>margin</code> hack 会让父元素的滚动区域异常，出现&quot;页面多出一大截空白无法滚动到底&quot;的问题，用 <code>overflow: hidden</code> 才勉强可接受。</li></ul><h3 id="q26-等分布局和自适应布局分别怎么实现" tabindex="-1"><a class="header-anchor" href="#q26-等分布局和自适应布局分别怎么实现" aria-hidden="true">#</a> Q26 等分布局和自适应布局分别怎么实现？</h3><p><strong>考察点</strong>：考场景判断与 <code>gap</code> 带来的写法变化，是日常最高频的布局需求。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：等分用 Flex 的 <code>flex: 1</code>（配 <code>min-width: 0</code>）或 Grid 的 <code>repeat(n, 1fr)</code>；自适应用 Grid 的 <code>auto-fit + minmax</code> 或 Flex 的 <code>flex-wrap</code> 配合百分比。</p></blockquote><ol><li>Flex 等分：子项 <code>flex: 1; min-width: 0</code>，数量不限都能等分。注意 <code>flex: 1</code> 是 <code>basis: 0%</code>，等价于忽略内容宽度。</li><li>Grid 等分：<code>grid-template-columns: repeat(4, 1fr)</code>，更适合固定列数的卡片网格，列宽与 <code>gap</code> 都由浏览器计算。</li><li>Grid 自适应：<code>repeat(auto-fit, minmax(240px, 1fr))</code> + <code>gap</code>，容器变窄自动减列，不用媒体查询。</li><li>Flex 自适应（老写法）：子项 <code>width: calc((100% - 3 * 16px) / 4)</code> 配合 <code>flex-wrap: wrap</code> 和 <code>margin</code> 间距，再用 <code>nth-child</code> 去掉末列多余间距；有了 <code>gap</code> 之后这类计算基本可以删掉。</li></ol><div class="language-css line-numbers-mode" data-ext="css"><pre class="language-css"><code><span class="token selector">.grid</span> <span class="token punctuation">{</span> <span class="token property">display</span><span class="token punctuation">:</span> grid<span class="token punctuation">;</span> <span class="token property">gap</span><span class="token punctuation">:</span> 16px<span class="token punctuation">;</span> <span class="token property">grid-template-columns</span><span class="token punctuation">:</span> <span class="token function">repeat</span><span class="token punctuation">(</span>4<span class="token punctuation">,</span> 1fr<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
<span class="token selector">.grid-auto</span> <span class="token punctuation">{</span> <span class="token property">display</span><span class="token punctuation">:</span> grid<span class="token punctuation">;</span> <span class="token property">gap</span><span class="token punctuation">:</span> 16px<span class="token punctuation">;</span>
  <span class="token property">grid-template-columns</span><span class="token punctuation">:</span> <span class="token function">repeat</span><span class="token punctuation">(</span>auto-fit<span class="token punctuation">,</span> <span class="token function">minmax</span><span class="token punctuation">(</span>240px<span class="token punctuation">,</span> 1fr<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>repeat(4, 1fr)</code> 里放了 5 个子元素会怎样？答：第 5 个会进入隐式生成的第 2 行，需要 <code>grid-auto-rows</code> 控制高度或调整列数。</li><li>陷阱：用 <code>width: 25%</code> 加 <code>gap</code> 做四等分，结果总宽超过 100% 导致换行错位，必须改用 <code>calc()</code> 或 <code>1fr</code>。</li><li>陷阱：Flex 等分不写 <code>min-width: 0</code>，含长文本的那一列被撑宽，看起来&quot;没有等分&quot;。</li></ul><h3 id="q27-margin-auto-为什么能让绝对定位元素居中" tabindex="-1"><a class="header-anchor" href="#q27-margin-auto-为什么能让绝对定位元素居中" aria-hidden="true">#</a> Q27 margin: auto 为什么能让绝对定位元素居中？</h3><p><strong>考察点</strong>：原理题，考对&quot;过约束&quot;和剩余空间分配的理解，能答出就是深挖得分点。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：绝对定位元素在四个偏移值（<code>top</code> / <code>right</code> / <code>bottom</code> / <code>left</code>）都为 0、且宽高确定时，包含块被元素和偏移&quot;过约束&quot;，<code>margin: auto</code> 会把水平与垂直方向的剩余空间平分，从而实现两个方向同时居中。</p></blockquote><ol><li>普通块级元素的 <code>margin: auto</code> 只能水平居中，因为垂直方向的 <code>height: auto</code> 由内容决定，不存在&quot;剩余空间&quot;可分配（除非父级有确定高度且元素高度确定）。</li><li>绝对定位元素一旦 <code>left: 0; right: 0</code> 并且设置了 <code>width</code>，水平方向的等式被固定，<code>margin-left/right: auto</code> 就参与求解，各自得到 <code>(包含块宽度 - 元素宽度) / 2</code>。</li><li>同理 <code>top: 0; bottom: 0</code> 加上确定的 <code>height</code>，垂直方向也成立，于是 <code>margin: auto</code> 一行实现水平垂直居中。</li></ol><div class="language-css line-numbers-mode" data-ext="css"><pre class="language-css"><code><span class="token selector">.center</span> <span class="token punctuation">{</span>
  <span class="token property">position</span><span class="token punctuation">:</span> absolute<span class="token punctuation">;</span> <span class="token property">inset</span><span class="token punctuation">:</span> 0<span class="token punctuation">;</span> <span class="token comment">/* 等价 top/right/bottom/left: 0 */</span>
  <span class="token property">margin</span><span class="token punctuation">:</span> auto<span class="token punctuation">;</span>
  <span class="token property">width</span><span class="token punctuation">:</span> 240px<span class="token punctuation">;</span> <span class="token property">height</span><span class="token punctuation">:</span> 160px<span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ol start="4"><li>与 <code>transform: translate(-50%, -50%)</code> 的区别：后者不需要确定尺寸，但 <code>transform</code> 会创建包含块与层叠上下文，可能影响子元素 <code>fixed</code> 定位；<code>margin: auto</code> 方案没有这个副作用，代价是必须有确定尺寸。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：不给宽高只用 <code>margin: auto</code> 能居中吗？答：不能。宽高由内容撑开时元素会贴着起点，没有剩余空间可分配。</li><li>陷阱：以为 <code>margin: auto</code> 在普通流里也能垂直居中。它需要&quot;确定高度 + 过约束&quot;这两个前提，普通块级元素做不到。</li><li>陷阱：把 <code>inset: 0</code> 当成&quot;宽高铺满&quot;。它只是把四个偏移设为 0，元素的尺寸仍由 <code>width/height</code> 或内容决定。</li></ul><h3 id="q28-width-100-和-width-auto-有什么区别" tabindex="-1"><a class="header-anchor" href="#q28-width-100-和-width-auto-有什么区别" aria-hidden="true">#</a> Q28 width: 100% 和 width: auto 有什么区别？</h3><p><strong>考察点</strong>：看似基础，实为易混点，考是否理解块级元素的宽度计算规则。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：块级元素的 <code>width: auto</code> 是&quot;自动填满包含块内容宽度并扣掉自身的 margin / border / padding&quot;，<code>width: 100%</code> 是&quot;严格等于包含块内容宽度的 100%，再额外加上 padding 和 border（content-box 下）&quot;，因此更容易溢出。</p></blockquote><ol><li><code>auto</code> 的解算是：<code>width = 包含块内容宽度 - margin - border - padding</code>，所以加了 padding 也不会溢出，是块级元素的默认行为。</li><li><code>100%</code> 只规定内容框宽度等于包含块内容宽度，在 <code>content-box</code> 下再加上左右 padding、border 就会超出容器，出现横向滚动条；配 <code>box-sizing: border-box</code> 后两者表现接近。</li><li><code>auto</code> 的额外能力：可以被弹性布局、表格布局、<code>margin: auto</code> 等规则&quot;再分配&quot;（剩余空间平分、按内容收缩），而 <code>100%</code> 是硬值，不参与这些计算。</li><li>实践结论：普通流里边栏、卡片用 <code>auto</code> 或干脆不写；需要显式撑满且带 padding 时写 <code>width: 100%</code> 并配合 <code>box-sizing: border-box</code>。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么输入框设 <code>width: 100%</code> 加 padding 后撑破了父级？答：<code>input</code> 默认是 content-box，padding 与 border 额外增加宽度；改 <code>box-sizing: border-box</code> 即可。</li><li>陷阱：认为 <code>width: auto</code> 一定小于 <code>100%</code>。在 <code>border-box</code> 且无 padding 时两者数值相同，差异在约束语义与可参与的计算上。</li><li>陷阱：把 <code>width: 100%</code> 用在绝对定位元素上，误以为会撑满视口。它参照的是包含块，不是视口。</li></ul><h3 id="q29-px、em、rem、-、vh-vw、ch-ex、rpx-各有什么区别-怎么选" tabindex="-1"><a class="header-anchor" href="#q29-px、em、rem、-、vh-vw、ch-ex、rpx-各有什么区别-怎么选" aria-hidden="true">#</a> Q29 px、em、rem、%、vh/vw、ch/ex、rpx 各有什么区别？怎么选？</h3><p><strong>考察点</strong>：单位体系是 CSS 基础的&quot;照妖镜&quot;，考对照与选型判断。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>px</code> 是绝对长度适合边框与固定间距，<code>rem</code> 相对根字号适合整体缩放与无障碍，<code>em</code> 相对自身/父级字号适合内联缩放但会层层叠加，<code>%</code> 参照包含块，<code>vh/vw</code> 参照视口，<code>ch</code> / <code>ex</code> 是字体相关单位，<code>rpx</code> 是小程序特有的响应式像素。</p></blockquote><table><thead><tr><th>单位</th><th>参照</th><th>典型用途</th><th>注意点</th></tr></thead><tbody><tr><td><code>px</code></td><td>绝对像素</td><td>边框、图标、小间距</td><td>不随用户字号缩放</td></tr><tr><td><code>em</code></td><td>元素自身（<code>font-size</code> 用父级）</td><td>组件内等比缩放</td><td>嵌套会累乘，容易失控</td></tr><tr><td><code>rem</code></td><td>根元素 <code>html</code> 的 <code>font-size</code></td><td>整体适配、间距体系</td><td>根字号被改会全局放大</td></tr><tr><td><code>%</code></td><td>包含块（<code>padding</code> 也按宽度）</td><td>流体宽度、栅格</td><td>高度百分比依赖父级确定高度</td></tr><tr><td><code>vh</code> / <code>vw</code></td><td>视口高度 / 宽度</td><td>全屏区块</td><td>移动端地址栏导致 100vh 偏大</td></tr><tr><td><code>ch</code></td><td>字符 &quot;0&quot; 的宽度</td><td>输入框宽度、文本行宽</td><td>受字体影响</td></tr><tr><td><code>ex</code></td><td>小写字母 x 的高度</td><td>少量微调</td><td>各字体差异大，少用</td></tr><tr><td><code>rpx</code></td><td>小程序 750 设计稿</td><td>小程序尺寸</td><td>仅小程序支持，换算 750rpx = 屏宽</td></tr></tbody></table><ol><li>选型建议：用 <code>rem</code> 建立间距与字号体系，固定细节用 <code>px</code>，全屏区块用 <code>dvh</code> / <code>svh</code> 替代 <code>vh</code>，小程序用 <code>rpx</code>。</li><li><code>em</code> 的陷阱：<code>padding: 1em</code> 相对的是该元素自己的 <code>font-size</code>，而 <code>font-size: 1.2em</code> 相对父元素，嵌套多层时会累乘。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>rem</code> 适配有什么代价？答：修改根字号会整体缩放，第三方组件里写死的 <code>px</code> 不跟随，容易混用失控；现代更推荐搭配 <code>clamp()</code> 做有限度缩放。</li><li>陷阱：认为 <code>vw</code> 不受滚动条影响。桌面浏览器 <code>100vw</code> 通常包含滚动条宽度，会出现横向滚动条，可用 <code>100%</code> 或 <code>scrollbar-gutter</code> 规避。</li><li>陷阱：把 <code>%</code> 高度的失效归因于&quot;浏览器 bug&quot;。根因是父级 <code>height: auto</code>，百分比高度无法解析。</li></ul><h3 id="q30-calc、min、max、clamp-怎么用-有哪些注意事项" tabindex="-1"><a class="header-anchor" href="#q30-calc、min、max、clamp-怎么用-有哪些注意事项" aria-hidden="true">#</a> Q30 calc、min、max、clamp 怎么用？有哪些注意事项？</h3><p><strong>考察点</strong>：CSS 数学函数是进阶必备，考语法细节与组合用法。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>calc()</code> 做单位混合运算，<code>min()</code> / <code>max()</code> 取极值实现上限下限，<code>clamp(最小, 理想, 最大)</code> 是&quot;响应式字号与容器宽度&quot;的一行解法。</p></blockquote><ol><li><code>calc()</code> 支持加减乘除与不同单位混算，注意 <code>+</code> <code>-</code> 两侧必须有空格（否则被解析成符号），乘除只能与数字运算。</li><li><code>min()</code> / <code>max()</code> 接收多个值取最小 / 最大，常用于给 <code>width</code> 设上限：<code>width: min(100%, 1200px)</code>，比 <code>max-width</code> 更灵活（可直接用于 grid 的 <code>minmax</code>）。</li><li><code>clamp(min, val, max)</code> 等价于 <code>max(min, min(val, max))</code>，当 <code>min</code> 大于 <code>max</code> 时以 <code>min</code> 为准；常用于 <code>font-size: clamp(14px, 2vw + 8px, 20px)</code> 这类流体字号。</li><li>组合技巧：<code>width: clamp(280px, 60vw, 900px)</code>、<code>grid-template-columns: repeat(auto-fit, minmax(max(200px, 25%), 1fr))</code>。所有函数都可用于绝大多数长度属性，但一般不能用于媒体查询条件与 <code>@media</code> 的断点值。</li></ol><div class="language-css line-numbers-mode" data-ext="css"><pre class="language-css"><code><span class="token selector">.card</span> <span class="token punctuation">{</span> <span class="token property">width</span><span class="token punctuation">:</span> <span class="token function">min</span><span class="token punctuation">(</span>100% - 32px<span class="token punctuation">,</span> 1080px<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token property">padding</span><span class="token punctuation">:</span> <span class="token function">clamp</span><span class="token punctuation">(</span>12px<span class="token punctuation">,</span> 2vw<span class="token punctuation">,</span> 24px<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
<span class="token selector">.title</span> <span class="token punctuation">{</span> <span class="token property">font-size</span><span class="token punctuation">:</span> <span class="token function">clamp</span><span class="token punctuation">(</span>16px<span class="token punctuation">,</span> 1.5rem + 0.5vw<span class="token punctuation">,</span> 24px<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
<span class="token comment">/* 注意：calc 的加减号两侧必须有空格 */</span>
<span class="token selector">.offset</span> <span class="token punctuation">{</span> <span class="token property">margin-top</span><span class="token punctuation">:</span> <span class="token function">calc</span><span class="token punctuation">(</span>100% - 40px<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>min()</code> / <code>max()</code> 和 CSS 的 <code>min-width</code> / <code>max-width</code> 有什么区别？答：前者是取值函数，可以和其他值混算、可用于 <code>grid-template-columns</code> 等任意长度位置；后者是约束属性，只作用于尺寸属性。</li><li>陷阱：<code>calc(100%-40px)</code> 不生效，因为缺少空格导致解析失败，这是最常见的低级 bug。</li><li>陷阱：用 <code>clamp()</code> 却把最小值和最大值写反，浏览器会取最小值，看起来&quot;没生效&quot;。</li></ul><h3 id="q31-min-content、max-content、fit-content-分别是什么意思" tabindex="-1"><a class="header-anchor" href="#q31-min-content、max-content、fit-content-分别是什么意思" aria-hidden="true">#</a> Q31 min-content、max-content、fit-content 分别是什么意思？</h3><p><strong>考察点</strong>：内在尺寸（intrinsic size）关键字，考对内容驱动布局的理解，属于深挖题。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>min-content</code> 是最窄也不得不这么宽的尺寸（最宽的那个不可断行内容），<code>max-content</code> 是内容完全不断行的理想宽度，<code>fit-content</code> 是&quot;在可用空间内尽量贴合内容，但不超出容器&quot;。</p></blockquote><ol><li><code>min-content</code>：取内容中&quot;最宽的最小不可断单元&quot;，例如文字取最长单词、图片取原宽。适合想让元素尽量窄、并且允许换行的场景。</li><li><code>max-content</code>：内容不被压缩换行时的完整宽度，常见于让标题、标签不被折断：<code>width: max-content</code>。</li><li><code>fit-content</code>：等价于 <code>min(max-content, max(min-content, 可用空间))</code>，即&quot;内容小就跟内容一样宽，内容大就在可用空间内换行&quot;，用在按钮、标签上非常自然。</li><li>带参数的 <code>fit-content(300px)</code> 表示上限为 300px 的 fit-content，可用于 Grid 轨道与容器尺寸。</li></ol><div class="language-css line-numbers-mode" data-ext="css"><pre class="language-css"><code><span class="token selector">.tag</span>   <span class="token punctuation">{</span> <span class="token property">width</span><span class="token punctuation">:</span> fit-content<span class="token punctuation">;</span> <span class="token property">padding</span><span class="token punctuation">:</span> 0 8px<span class="token punctuation">;</span> <span class="token punctuation">}</span>   <span class="token comment">/* 宽度贴合文字，不撑满整行 */</span>
<span class="token selector">.title</span> <span class="token punctuation">{</span> <span class="token property">width</span><span class="token punctuation">:</span> max-content<span class="token punctuation">;</span> <span class="token property">max-width</span><span class="token punctuation">:</span> 100%<span class="token punctuation">;</span> <span class="token punctuation">}</span>  <span class="token comment">/* 不折行，但不超出父级 */</span>
<span class="token selector">.col</span>   <span class="token punctuation">{</span> <span class="token property">grid-template-columns</span><span class="token punctuation">:</span> min-content 1fr<span class="token punctuation">;</span> <span class="token punctuation">}</span> <span class="token comment">/* 第一列尽量窄 */</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>fit-content</code> 和 <code>inline-block</code> 有什么区别？答：<code>inline-block</code> 也是收缩包裹，但它是行内级盒子、会受空白节点影响；<code>fit-content</code> 是块级元素上的宽度取值，语义更清晰。</li><li>陷阱：把 <code>max-content</code> 当成&quot;最大宽度&quot;。它是内容理想宽度，可能比容器还宽并造成溢出，通常要配 <code>max-width: 100%</code>。</li><li>陷阱：在 Grid 里忘了 <code>fr</code> 的最小值是 <code>auto</code>，直接写 <code>1fr</code> 时列会被 <code>max-content</code> 撑开，需要写成 <code>minmax(0, 1fr)</code>。</li></ul><h3 id="q32-aspect-ratio-怎么用-没有它之前是怎么做的" tabindex="-1"><a class="header-anchor" href="#q32-aspect-ratio-怎么用-没有它之前是怎么做的" aria-hidden="true">#</a> Q32 aspect-ratio 怎么用？没有它之前是怎么做的？</h3><p><strong>考察点</strong>：现代 CSS 的实用属性，考写法与兼容思路，顺便看是否真的做过响应式。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>aspect-ratio</code> 直接声明元素的宽高比（如 <code>16 / 9</code>），让元素按宽度自动算高度；它出现之前用 <code>padding-top</code> 百分比撑高的 hack。</p></blockquote><ol><li>语法：<code>aspect-ratio: &lt;宽度&gt; / &lt;高度&gt;</code>，也支持单个数字（<code>1</code> 等价于 <code>1 / 1</code>）。元素的某一维由布局决定，另一维按比例推导。</li><li>典型用法是媒体占位：卡片图片容器设 <code>aspect-ratio: 16 / 9; width: 100%</code>，再让 <code>img</code> 用 <code>width: 100%; height: 100%; object-fit: cover</code>，就不会出现加载前后布局跳动（避免 CLS）。</li><li>失效情形：宽高<strong>都</strong>被显式指定时，<code>aspect-ratio</code> 被忽略；元素内容溢出也会撑破比例，通常要配 <code>overflow: hidden</code>。</li><li>旧方案对比：外层 <code>position: relative; padding-top: 56.25%</code>（即 9/16），内层绝对定位铺满。原理是上下 <code>padding</code> 的百分比按包含块<strong>宽度</strong>计算，所以 padding 能被当成高度用。</li></ol><div class="language-css line-numbers-mode" data-ext="css"><pre class="language-css"><code><span class="token selector">.thumb</span> <span class="token punctuation">{</span> <span class="token property">aspect-ratio</span><span class="token punctuation">:</span> 16 / 9<span class="token punctuation">;</span> <span class="token property">width</span><span class="token punctuation">:</span> 100%<span class="token punctuation">;</span> <span class="token property">overflow</span><span class="token punctuation">:</span> hidden<span class="token punctuation">;</span> <span class="token property">border-radius</span><span class="token punctuation">:</span> 8px<span class="token punctuation">;</span> <span class="token punctuation">}</span>
<span class="token selector">.thumb &gt; img</span> <span class="token punctuation">{</span> <span class="token property">width</span><span class="token punctuation">:</span> 100%<span class="token punctuation">;</span> <span class="token property">height</span><span class="token punctuation">:</span> 100%<span class="token punctuation">;</span> <span class="token property">object-fit</span><span class="token punctuation">:</span> cover<span class="token punctuation">;</span> <span class="token punctuation">}</span>
<span class="token comment">/* 旧方案：.thumb { position: relative; padding-top: 56.25%; } */</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：图片本身有原始宽高比，为什么还要设 <code>aspect-ratio</code>？答：图片未加载完成时元素高度为 0，会让下方内容跳动；声明比例可以提前占位，也能统一不同尺寸图片的展示比例。</li><li>陷阱：给 <code>img</code> 同时设 <code>width: 100%; height: 300px; aspect-ratio: 16/9</code>，比例不生效因为宽高都确定了。</li><li>陷阱：忘记 <code>object-fit</code>，图片被拉伸变形，面试官常顺着问&quot;怎么保证图片不变形&quot;。</li></ul><h3 id="q33-object-fit-是做什么的-图片变形怎么彻底解决" tabindex="-1"><a class="header-anchor" href="#q33-object-fit-是做什么的-图片变形怎么彻底解决" aria-hidden="true">#</a> Q33 object-fit 是做什么的？图片变形怎么彻底解决？</h3><p><strong>考察点</strong>：图片处理是业务高频，考 <code>object-fit</code> 与前后的替代方案。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>object-fit</code> 决定替换元素（图片、视频）在其内容框内的填充方式，<code>cover</code> 保持比例裁剪填满、<code>contain</code> 保持比例完整显示，彻底解决图片被拉伸变形的问题。</p></blockquote><ol><li>取值：<code>fill</code>（默认，强行拉伸，会变形）、<code>contain</code>（保持比例完整显示，可能留白）、<code>cover</code>（保持比例裁剪填满，可能切掉边缘）、<code>none</code>（保持原始尺寸，可能溢出或留白）、<code>scale-down</code>（在 <code>none</code> 与 <code>contain</code> 中取更小的那个）。</li><li>使用前提：元素本身要有确定的宽高（或 <code>aspect-ratio</code>），否则 <code>object-fit</code> 无从计算。</li><li>配 <code>object-position</code> 控制裁剪位置，默认 <code>50% 50%</code> 居中，头像常用 <code>object-position: center top</code> 保住脸部。</li><li>替代方案：背景图 <code>background-size: cover / contain</code> 加 <code>background-position</code>；老浏览器可用&quot;容器 <code>overflow: hidden</code> + 图片 <code>min-width/min-height: 100%</code> 加定位&quot;或 <code>padding-top</code> 占位 + 绝对定位。</li></ol><div class="language-css line-numbers-mode" data-ext="css"><pre class="language-css"><code><span class="token selector">.avatar</span> <span class="token punctuation">{</span> <span class="token property">width</span><span class="token punctuation">:</span> 64px<span class="token punctuation">;</span> <span class="token property">height</span><span class="token punctuation">:</span> 64px<span class="token punctuation">;</span> <span class="token property">border-radius</span><span class="token punctuation">:</span> 50%<span class="token punctuation">;</span> <span class="token property">overflow</span><span class="token punctuation">:</span> hidden<span class="token punctuation">;</span> <span class="token punctuation">}</span>
<span class="token selector">.avatar img</span> <span class="token punctuation">{</span> <span class="token property">width</span><span class="token punctuation">:</span> 100%<span class="token punctuation">;</span> <span class="token property">height</span><span class="token punctuation">:</span> 100%<span class="token punctuation">;</span> <span class="token property">object-fit</span><span class="token punctuation">:</span> cover<span class="token punctuation">;</span> <span class="token property">object-position</span><span class="token punctuation">:</span> center top<span class="token punctuation">;</span> <span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>cover</code> 和 <code>contain</code> 怎么选？答：需要视觉统一、允许裁剪用 <code>cover</code>（缩略图、封面）；必须看到完整内容用 <code>contain</code>（证件照、图表、二维码）。</li><li>陷阱：把 <code>object-fit</code> 用在普通 <code>div</code> 上。它只对替换元素（<code>img</code> / <code>video</code> / <code>canvas</code>）生效，普通元素要用 <code>background-size</code>。</li><li>陷阱：只写了 <code>object-fit</code> 没给容器尺寸，图片按原始尺寸显示，比例看起来&quot;没起作用&quot;。</li></ul><h3 id="q34-css-选择器优先级怎么计算-not、-is、-where-的权重是多少" tabindex="-1"><a class="header-anchor" href="#q34-css-选择器优先级怎么计算-not、-is、-where-的权重是多少" aria-hidden="true">#</a> Q34 CSS 选择器优先级怎么计算？:not、:is、:where 的权重是多少？</h3><p><strong>考察点</strong>：权重计算是必考题，<code>where</code> 与 <code>:is</code> 的差异是进阶加分点。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：优先级按 <code>(内联, ID, 类/属性/伪类, 元素/伪元素)</code> 四元组比较，从左到右逐级比大小；<code>:is()</code> / <code>:not()</code> 取参数中权重<strong>最高</strong>的那个，<code>:where()</code> 权重恒为 0。</p></blockquote><ol><li>权重分级：内联样式 <code>style=&quot;&quot;</code> 记为 (1,0,0,0)；ID 选择器 (0,1,0,0)；类、属性选择器、伪类 (0,0,1,0)；元素、伪元素 (0,0,0,1)；通配符 <code>*</code>、组合符 <code>&gt;</code> <code>+</code> <code>~</code> 不贡献权重。</li><li>比较规则：先比第一位，相同再比下一位；同权重时后出现的生效（层叠顺序：重要性 &gt; 来源 &gt; 权重 &gt; 顺序）。<code>!important</code> 是独立性优先级，不参与四元组比较。</li><li>函数伪类的差异：<code>:is(.a, #b)</code> 取最高权重 <code>#b</code>，整体按 ID 计算；<code>:not(.a, .b)</code> 同样取参数最高权重；<code>:where(.a, #b)</code> 无论写什么都按 0 计算。</li></ol><div class="language-css line-numbers-mode" data-ext="css"><pre class="language-css"><code><span class="token comment">/* 计算示例 */</span>
ul li.active       <span class="token comment">/* (0,0,1,2) */</span>
#nav .<span class="token property">item</span><span class="token punctuation">:</span>hover   <span class="token comment">/* (0,1,1,1) */</span>
<span class="token punctuation">:</span><span class="token function">is</span><span class="token punctuation">(</span>#a<span class="token punctuation">,</span> .b<span class="token punctuation">)</span> .c     <span class="token comment">/* (0,1,1,0) —— 取最高 #a */</span>
<span class="token punctuation">:</span><span class="token function">where</span><span class="token punctuation">(</span>#a<span class="token punctuation">)</span> .c      <span class="token comment">/* (0,0,1,0) —— where 归零 */</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ol start="4"><li>工程建议：优先用 <code>:where()</code> 写基础样式（权重 0，任何业务样式都能覆盖），用 <code>:is()</code> 简化多选择器列举；不要靠堆 ID 和 <code>!important</code> 提升权重。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>:where()</code> 的实际价值是什么？答：写组件基础样式时权重为 0，使用方用任何选择器都能覆盖，不需要 <code>!important</code>，是做主题与样式重置的利器。</li><li>陷阱：认为&quot;类选择器写得多权重就高&quot;。位与位之间不进位，写 11 个类也压不过 1 个 ID。</li><li>陷阱：把 <code>!important</code> 算成&quot;权重加 1000&quot;。它是独立维度，同源同权重下才比较，且用户样式的 <code>!important</code> 高于作者样式。</li></ul><h3 id="q35-伪类和伪元素有什么区别-常用的各有哪些" tabindex="-1"><a class="header-anchor" href="#q35-伪类和伪元素有什么区别-常用的各有哪些" aria-hidden="true">#</a> Q35 伪类和伪元素有什么区别？常用的各有哪些？</h3><p><strong>考察点</strong>：概念辨析 + API 熟练度，单冒号/双冒号写错会当场露怯。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：伪类（pseudo-class）用单冒号表示元素的<strong>状态或位置</strong>，伪元素（pseudo-element）用双冒号表示&quot;凭空生成的<strong>虚拟元素</strong>&quot;。</p></blockquote><ol><li>伪类：基于文档树之外的信息选中元素，如 <code>:hover</code>、<code>:focus</code>、<code>:active</code>、<code>:visited</code>、<code>:first-child</code>、<code>:last-child</code>、<code>:nth-child(2n+1)</code>、<code>:not()</code>、<code>:is()</code>、<code>:where()</code>、<code>:has()</code>、<code>:disabled</code>、<code>:checked</code>、<code>:focus-visible</code>。</li><li>伪元素：<code>::before</code>、<code>::after</code>、<code>::first-line</code>、<code>::first-letter</code>、<code>::placeholder</code>、<code>::selection</code>、<code>::marker</code>、<code>::backdrop</code>。</li><li>历史与规范：CSS2 里两者都用单冒号，CSS3 起为区分引入双冒号；<code>::before</code> / <code>::after</code> / <code>::first-line</code> / <code>::first-letter</code> 为了兼容仍支持单冒号写法，其余必须双冒号。</li><li>关键区别：伪类不改变 DOM 结构、只是&quot;选中&quot;已有元素的状态；伪元素会产生一个渲染盒子，可以设 <code>content</code>、<code>display</code>、尺寸，但仍不在 DOM 里，JS 拿不到节点，只能通过 CSS 变量或类名控制。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>:nth-child</code> 和 <code>:nth-of-type</code> 有什么区别？答：前者按父元素下所有子元素的序号计数，后者只按同类型标签计数，混排列表时会得到不同结果。</li><li>陷阱：说伪元素&quot;会被爬虫和屏幕阅读器读到&quot;。<code>::before</code> 生成的内容语义有限，重要信息不要只写在 <code>content</code> 里。</li><li>陷阱：用 <code>::before</code> 给 <code>&lt;img&gt;</code> / <code>&lt;input&gt;</code> 加装饰。替换元素不能生成伪元素，这是最常见的&quot;为什么没效果&quot;。</li></ul><h3 id="q36-before-和-after-的-content-有哪些写法-常用在哪些场景" tabindex="-1"><a class="header-anchor" href="#q36-before-和-after-的-content-有哪些写法-常用在哪些场景" aria-hidden="true">#</a> Q36 ::before 和 ::after 的 content 有哪些写法？常用在哪些场景？</h3><p><strong>考察点</strong>：基础组件开发必备，考 <code>content</code> 取值与典型用法。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>content</code> 是 <code>::before</code> / <code>::after</code> 生效的<strong>必要条件</strong>，即使内容为空也要写 <code>content: &quot;&quot;</code>；它们常用于清浮动、装饰图标、角标、提示三角等&quot;纯视觉元素&quot;。</p></blockquote><ol><li><code>content</code> 常用取值：<code>&quot;&quot;</code>（空，做纯装饰盒子）、<code>&quot;文字&quot;</code>、<code>attr(data-x)</code>（读属性值，做角标很方便）、<code>counter(名字)</code>（配合计数器）、<code>url(...)</code>（图片，支持度一般）、<code>open-quote</code> / <code>close-quote</code>。</li><li>默认 <code>display: inline</code>，要设宽高必须改 <code>display: block</code> 或 <code>inline-block</code>；它们会作为父元素的第一个 / 最后一个子元素参与布局。</li><li>常用场景：清浮动（<code>clearfix</code>）、图标字体或装饰线、tooltip 的三角形（<code>border</code> 技巧）、表单必填星号、评分星星、角标数字、占位蒙层。</li></ol><div class="language-css line-numbers-mode" data-ext="css"><pre class="language-css"><code><span class="token selector">.item::after</span> <span class="token punctuation">{</span> <span class="token property">content</span><span class="token punctuation">:</span> <span class="token function">attr</span><span class="token punctuation">(</span>data-badge<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token property">display</span><span class="token punctuation">:</span> inline-block<span class="token punctuation">;</span>
  <span class="token property">margin-left</span><span class="token punctuation">:</span> 4px<span class="token punctuation">;</span> <span class="token property">padding</span><span class="token punctuation">:</span> 0 6px<span class="token punctuation">;</span> <span class="token property">font-size</span><span class="token punctuation">:</span> 12px<span class="token punctuation">;</span>
  <span class="token property">color</span><span class="token punctuation">:</span> #fff<span class="token punctuation">;</span> <span class="token property">background</span><span class="token punctuation">:</span> #f5222d<span class="token punctuation">;</span> <span class="token property">border-radius</span><span class="token punctuation">:</span> 8px<span class="token punctuation">;</span> <span class="token punctuation">}</span>
<span class="token comment">/* 三角形：border 技巧 */</span>
<span class="token selector">.arrow::before</span> <span class="token punctuation">{</span> <span class="token property">content</span><span class="token punctuation">:</span> <span class="token string">&quot;&quot;</span><span class="token punctuation">;</span> <span class="token property">display</span><span class="token punctuation">:</span> block<span class="token punctuation">;</span> <span class="token property">width</span><span class="token punctuation">:</span> 0<span class="token punctuation">;</span> <span class="token property">height</span><span class="token punctuation">:</span> 0<span class="token punctuation">;</span>
  <span class="token property">border</span><span class="token punctuation">:</span> 6px solid transparent<span class="token punctuation">;</span> <span class="token property">border-bottom-color</span><span class="token punctuation">:</span> #333<span class="token punctuation">;</span> <span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么给 <code>::after</code> 设了 <code>width</code> 没生效？答：伪元素默认行内，宽高无效，需要 <code>display: block</code> / <code>inline-block</code>。</li><li>陷阱：以为伪元素能放在 <code>content</code> 之外的 DOM 位置。它只能出现在所属元素的内容首尾，且不参与 DOM 查询。</li><li>陷阱：用 <code>content</code> 承载业务文案。文案应写在 HTML 或由 JS 渲染，伪元素内容不可选中、不可访问、无法被测试查询。</li></ul><h3 id="q37-哪些-css-属性可以继承-哪些不能" tabindex="-1"><a class="header-anchor" href="#q37-哪些-css-属性可以继承-哪些不能" aria-hidden="true">#</a> Q37 哪些 CSS 属性可以继承？哪些不能？</h3><p><strong>考察点</strong>：考记忆归类 + 是否理解&quot;继承的设计逻辑&quot;。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：与文字排版相关的属性（<code>color</code>、<code>font-*</code>、<code>line-height</code>、<code>text-align</code>、<code>visibility</code>、<code>cursor</code>、<code>list-style</code>）默认继承，与盒子模型和布局相关的属性（<code>width</code>、<code>margin</code>、<code>padding</code>、<code>border</code>、<code>background</code>、<code>display</code>、<code>position</code>、<code>overflow</code>、<code>z-index</code>）默认不继承。</p></blockquote><ol><li>可继承：<code>color</code>、<code>font-family</code> / <code>font-size</code> / <code>font-weight</code> / <code>font-style</code>、<code>line-height</code>、<code>letter-spacing</code>、<code>word-spacing</code>、<code>text-align</code>、<code>text-indent</code>、<code>text-transform</code>、<code>white-space</code>、<code>visibility</code>、<code>cursor</code>、<code>list-style-*</code>、<code>direction</code>。</li><li>不可继承：<code>width</code> / <code>height</code>、<code>margin</code> / <code>padding</code>、<code>border</code>、<code>background</code>、<code>display</code>、<code>position</code>、<code>float</code> / <code>clear</code>、<code>overflow</code>、<code>z-index</code>、<code>vertical-align</code>、<code>opacity</code>（注意：<code>opacity</code> 不继承，但父级透明会视觉上影响子元素）。</li><li>设计逻辑：继承是为了让&quot;文本样式&quot;一处声明、全局生效；布局属性如果继承，会让每个子元素都带着父级的宽高和定位，无法使用。</li><li>显式控制的关键字：<code>inherit</code>（强制继承父级计算值）、<code>initial</code>（回到规范初始值）、<code>unset</code>（可继承属性等同 <code>inherit</code>，否则等同 <code>initial</code>）、<code>revert</code>（回到浏览器或用户样式表的取值，常用于重置）。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>line-height: 1.5</code> 为什么子元素会继承得很好，<code>150%</code> 不会？答：无单位数值继承的是比例，百分比继承的是计算后的绝对值（见 Q14）。</li><li>陷阱：说 <code>text-align</code> 不继承。它可继承，所以给父级设 <code>text-align: center</code>，内部所有行内内容都会居中，包括你不想居中的按钮文字。</li><li>陷阱：把 <code>visibility: hidden</code> 当成不可继承。它可继承，但子元素可以显式写 <code>visibility: visible</code> 重新显示，这是它与 <code>display: none</code> 的重要差别。</li></ul><h3 id="q38-important-的层级有多高-什么时候该用" tabindex="-1"><a class="header-anchor" href="#q38-important-的层级有多高-什么时候该用" aria-hidden="true">#</a> Q38 !important 的层级有多高？什么时候该用？</h3><p><strong>考察点</strong>：进阶细节题，考的是层叠规则的完整顺序，而不是&quot;加叹号就能盖住一切&quot;。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>!important</code> 高于同源的普通声明，但<strong>不高于</strong>用户样式表的 <code>!important</code>，也永远盖不过 <code>transition</code>；相同重要性的声明之间仍按常规权重和顺序比较。</p></blockquote><ol><li>完整层叠顺序（优先级从高到低）：<code>transition</code> 声明 → 用户代理（浏览器）样式表的 <code>!important</code> → 用户样式表的 <code>!important</code> → 作者样式表的 <code>!important</code> → 动画（<code>@keyframes</code>）声明 → 作者普通样式 → 用户普通样式 → 用户代理普通样式。</li><li>同源内的比较：同样是 <code>!important</code> 时，回退到常规规则——比较四元组权重，再比出现顺序，最后出现的胜出。</li><li>内联样式与 <code>!important</code>：内联样式权重高于任何选择器，想要覆盖它必须使用 <code>!important</code>（内联带 <code>!important</code> 则更难覆盖，通常只能改 DOM 或样式表来源）。</li><li>使用建议：只在覆盖第三方库、重置难以触及的样式、或提供&quot;可被用户覆盖的降级样式&quot;时使用；日常业务样式靠提高选择器特异性或调整引入顺序解决。</li></ol><div class="language-css line-numbers-mode" data-ext="css"><pre class="language-css"><code><span class="token comment">/* 反面示例：层层加叹号后无法维护 */</span>
<span class="token selector">.btn</span> <span class="token punctuation">{</span> <span class="token property">color</span><span class="token punctuation">:</span> red <span class="token important">!important</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么有时候加了 <code>!important</code> 还是不变？答：可能被更靠后的 <code>!important</code> 同权重声明覆盖、被 <code>transition</code> 覆盖，或该属性本身不可动画/被 <code>@keyframes</code> 接管；也可能样式被 <code>revert</code>、被 <code>all: unset</code> 重置。</li><li>陷阱：认为 <code>!important</code> 能覆盖内联样式之外的一切。它不能覆盖用户样式的 <code>!important</code>，也不能改变层叠上下文的遮挡关系。</li><li>陷阱：在组件库里滥用 <code>!important</code>，导致使用方无法定制主题，这是面试官最想听到的&quot;代价&quot;。</li></ul><h3 id="q39-overflow-有哪些取值-它和滚动容器、bfc-的关系是什么" tabindex="-1"><a class="header-anchor" href="#q39-overflow-有哪些取值-它和滚动容器、bfc-的关系是什么" aria-hidden="true">#</a> Q39 overflow 有哪些取值？它和滚动容器、BFC 的关系是什么？</h3><p><strong>考察点</strong>：滚动与裁剪是工程高频问题，考取值差异与副作用。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>overflow</code> 决定内容超出盒子时是显示、裁剪还是滚动，取值 <code>visible</code>（默认）/ <code>hidden</code> / <code>clip</code> / <code>scroll</code> / <code>auto</code>；只要设为非 <code>visible</code>，该元素就创建 BFC，并可能成为新的滚动容器。</p></blockquote><ol><li><code>visible</code>：不裁剪，内容溢出到盒子外显示，且可能影响外部布局。<code>hidden</code>：裁剪溢出部分，但仍<strong>可以通过 JS 或键盘滚到</strong>被裁掉的内容。<code>clip</code>：同样裁剪，且完全不可滚动（比 <code>hidden</code> 更彻底，也不会创建滚动容器）。</li><li><code>scroll</code>：始终显示滚动条轨道（即使内容没溢出，移动端与 macOS 会隐藏轨道）。<code>auto</code>：内容溢出时才出现滚动条，是最常用的取值。</li><li>与 BFC 的关系：非 <code>visible</code> 会创建 BFC，因此能清除浮动、阻止 margin 合并；代价是裁剪溢出内容，还会让内部 <code>position: sticky</code> 的参照变成该元素。</li><li>单轴设置规则：当 <code>overflow-x</code> 与 <code>overflow-y</code> 一个是 <code>visible</code> 另一个不是时，<code>visible</code> 会被计算成 <code>auto</code>（这是&quot;只想横向滚动却出现纵向滚动条&quot;的原因）。另外可用 <code>overscroll-behavior: contain</code> 阻止滚动链传导到页面、<code>scrollbar-gutter: stable</code> 预留滚动条位置避免布局抖动。</li></ol><div class="language-css line-numbers-mode" data-ext="css"><pre class="language-css"><code><span class="token selector">.scroll-x</span> <span class="token punctuation">{</span> <span class="token property">overflow-x</span><span class="token punctuation">:</span> auto<span class="token punctuation">;</span> <span class="token property">overflow-y</span><span class="token punctuation">:</span> hidden<span class="token punctuation">;</span> <span class="token property">white-space</span><span class="token punctuation">:</span> nowrap<span class="token punctuation">;</span> <span class="token punctuation">}</span>
<span class="token comment">/* 只写 overflow-x: auto 时，overflow-y 会变成 auto，可能多出纵向滚动条 */</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>overflow: auto</code> 的容器里元素 <code>position: sticky</code> 为什么不吸顶？答：该容器成了滚动容器，粘性定位相对它生效，若它自己不滚动就没有吸附距离（见 Q8）。</li><li>陷阱：用 <code>overflow: hidden</code> 清除浮动却裁掉了下拉菜单或 <code>box-shadow</code>，这是真实项目里最典型的副作用。</li><li>陷阱：认为 <code>overflow: hidden</code> 的内容不可滚动。用 <code>element.scrollTop</code> 或键盘 focus 仍可滚动，需要彻底不可滚用 <code>overflow: clip</code>。</li></ul><h3 id="q40-table-布局有哪些坑-border-collapse-有什么用" tabindex="-1"><a class="header-anchor" href="#q40-table-布局有哪些坑-border-collapse-有什么用" aria-hidden="true">#</a> Q40 table 布局有哪些坑？border-collapse 有什么用？</h3><p><strong>考察点</strong>：考表格语义与现代替代方案，这类&quot;老旧但常被问&quot;的知识点很能体现基础厚度。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>border-collapse: collapse</code> 让相邻单元格的边框合并为一条、<code>separate</code>（默认）则为每个单元格保留独立边框并用 <code>border-spacing</code> 控制间距；布局上有 <code>table-layout: fixed</code> 可让列宽由第一行或显式宽度决定、渲染更稳定。</p></blockquote><ol><li><code>border-collapse</code>：表格默认是 <code>separate</code>，相邻单元格之间有间距（用 <code>border-spacing</code> 控制，默认 2px），且会出现双重边框。<code>collapse</code> 合并边框，视觉上是一条线，是后台表格的标准做法。</li><li><code>table-layout</code>：<code>auto</code>（默认）按内容自动计算列宽，内容变化会导致列宽跳动；<code>fixed</code> 按表格宽度与首行 / <code>colgroup</code> 的宽度平均分配，渲染性能更好、列宽稳定，适合数据表格。</li><li>常见坑：<code>collapse</code> 下 <code>border-radius</code> 与单元格阴影不生效（相邻边框合并后无法画圆角）；<code>position: sticky</code> 的表头需要 <code>separate</code> 或单独处理；单元格内 <code>margin</code> 完全不生效，只能用 <code>padding</code>；高度 <code>height</code> 只是&quot;最小高度&quot;。</li><li>现代替代：布局用途不要用 <code>&lt;table&gt;</code>，用 Grid（<code>display: grid</code> / <code>grid-template-columns</code>）或 <code>display: table</code> 系列；数据表格仍应保留 <code>&lt;table&gt;</code> 语义以利无障碍。</li></ol><div class="language-css line-numbers-mode" data-ext="css"><pre class="language-css"><code><span class="token selector">.table</span> <span class="token punctuation">{</span> <span class="token property">width</span><span class="token punctuation">:</span> 100%<span class="token punctuation">;</span> <span class="token property">table-layout</span><span class="token punctuation">:</span> fixed<span class="token punctuation">;</span> <span class="token property">border-collapse</span><span class="token punctuation">:</span> collapse<span class="token punctuation">;</span> <span class="token punctuation">}</span>
<span class="token selector">.table th, .table td</span> <span class="token punctuation">{</span> <span class="token property">padding</span><span class="token punctuation">:</span> 8px 12px<span class="token punctuation">;</span> <span class="token property">border-bottom</span><span class="token punctuation">:</span> 1px solid #eee<span class="token punctuation">;</span> <span class="token punctuation">}</span>
<span class="token selector">.table th</span> <span class="token punctuation">{</span> <span class="token property">position</span><span class="token punctuation">:</span> sticky<span class="token punctuation">;</span> <span class="token property">top</span><span class="token punctuation">:</span> 0<span class="token punctuation">;</span> <span class="token property">background</span><span class="token punctuation">:</span> #fff<span class="token punctuation">;</span> <span class="token punctuation">}</span> <span class="token comment">/* 表头吸顶 */</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么固定表头 + <code>border-collapse: collapse</code> 下边框会消失？答：collapse 模式下边框由表格统一绘制，滚动时定位表头的边框可能不跟随，常见做法是改用 <code>border-collapse: separate; border-spacing: 0</code> 或给 <code>th</code> 单独写 <code>box-shadow</code>。</li><li>陷阱：说 <code>table-layout: fixed</code> 下所有列都等宽。它按首行单元格宽度或整体宽度均分，显式设过宽度的列仍按设定值。</li><li>陷阱：忘了单元格内 <code>margin</code> 无效，用 <code>margin</code> 调间距怎么都不动，改用 <code>padding</code>。</li></ul><h3 id="q41-gap-只能在-grid-用吗-flex-和其他布局支持吗" tabindex="-1"><a class="header-anchor" href="#q41-gap-只能在-grid-用吗-flex-和其他布局支持吗" aria-hidden="true">#</a> Q41 gap 只能在 Grid 用吗？Flex 和其他布局支持吗？</h3><p><strong>考察点</strong>：新特性的落地边界，考浏览器兼容意识。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>gap</code> 最早是 Grid 专属，现在 Flex 容器和多列布局（<code>column-count</code>）也已支持；普通块级流式布局不支持，仍要用 <code>margin</code> 模拟。</p></blockquote><ol><li>Grid 从一开始就支持 <code>gap</code> / <code>row-gap</code> / <code>column-gap</code>。Flex 容器支持 <code>gap</code> 是后来加入的（Chrome 84、Safari 14.1、Firefox 63 起），写法相同。</li><li>Flex 里 <code>gap</code> 的优势：不需要用 <code>margin</code> 拼间距，也不用 <code>:last-child</code> 去掉末位多余边距；<code>gap</code> 只在项目<strong>之间</strong>生成间距，不参与 <code>justify-content</code> 的剩余空间分配，因此 <code>justify-content: space-between</code> 与 <code>gap</code> 可以同时使用。</li><li>不支持的情况：多列布局外的普通块级排列、<code>float</code> 布局、老版本浏览器（如需支持 iOS 14 以下，得准备 <code>margin</code> 降级）。</li><li>另有 <code>grid-gap</code>、<code>grid-row-gap</code> 等旧别名仍在维护中，新代码统一写 <code>gap</code>。</li></ol><div class="language-css line-numbers-mode" data-ext="css"><pre class="language-css"><code><span class="token selector">.row</span> <span class="token punctuation">{</span> <span class="token property">display</span><span class="token punctuation">:</span> flex<span class="token punctuation">;</span> <span class="token property">gap</span><span class="token punctuation">:</span> 12px<span class="token punctuation">;</span> <span class="token punctuation">}</span>        <span class="token comment">/* 现代写法 */</span>
<span class="token selector">.row &gt; *</span> <span class="token punctuation">{</span> <span class="token property">margin-right</span><span class="token punctuation">:</span> 12px<span class="token punctuation">;</span> <span class="token punctuation">}</span>          <span class="token comment">/* 降级方案，需处理末位多余间距 */</span>
<span class="token selector">.row &gt; *:last-child</span> <span class="token punctuation">{</span> <span class="token property">margin-right</span><span class="token punctuation">:</span> 0<span class="token punctuation">;</span> <span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>gap</code> 与 <code>margin</code> 同时存在时怎么算？答：两者叠加，间距会变大，排查&quot;间距莫名变大&quot;时优先看是否两处都写了。</li><li>陷阱：说&quot;Flex 不支持 gap&quot;，这在 2020 年之后已经不成立，会被认为知识未更新；正确说法是&quot;支持，但需注意旧浏览器&quot;。</li><li>陷阱：把 <code>gap</code> 当作可以给任意元素加间距的通用属性。它不是 <code>margin</code> 的替代品，离开容器上下文没有效果。</li></ul><h3 id="q42-移动端-100vh-为什么会有问题-怎么解决" tabindex="-1"><a class="header-anchor" href="#q42-移动端-100vh-为什么会有问题-怎么解决" aria-hidden="true">#</a> Q42 移动端 100vh 为什么会有问题？怎么解决？</h3><p><strong>考察点</strong>：移动端适配的高频真问题，考对动态视口单位的了解。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：移动浏览器的地址栏会收起/展开，但 <code>vh</code> 历史上按&quot;最大视口&quot;计算，导致 <code>100vh</code> 比可视区域高，底部内容被地址栏挡住；解法是改用 <code>dvh</code>（动态视口高度）或 <code>svh</code> / <code>lvh</code>，旧环境用 <code>window.innerHeight</code> 写 CSS 变量兜底。</p></blockquote><ol><li>原因：<code>100vh</code> 取的是视口高度的最大值（大视口），当地址栏展开时实际可视高度更小，于是&quot;满屏&quot;元素会超出屏幕，出现页面能上下滚动一点、底部按钮被顶出视口的现象。</li><li>现代解法：<code>100dvh</code>（dynamic viewport height，随地址栏变化）、<code>100svh</code>（small，按最小的可视高度，最保守）、<code>100lvh</code>（large，按最大）。移动端满屏布局首选 <code>dvh</code>，需要&quot;绝不被挡住&quot;用 <code>svh</code>。Chromium 108+、Safari 15.4+ 起支持。</li><li>旧兼容解法：用 JS 监听 <code>resize</code> 与 <code>orientationchange</code>，把 <code>window.innerHeight</code> 写入 CSS 变量，样式里用 <code>height: var(--vh)</code>；注意加节流与 <code>visualViewport</code> 判断。</li><li>其他替代：用 <code>height: 100%</code> 链式撑满（需 <code>html, body { height: 100% }</code>）、或用 <code>position: fixed; inset: 0</code> 让元素脱离文档流贴合视口。</li></ol><div class="language-css line-numbers-mode" data-ext="css"><pre class="language-css"><code><span class="token selector">.screen</span> <span class="token punctuation">{</span> <span class="token property">height</span><span class="token punctuation">:</span> 100vh<span class="token punctuation">;</span> <span class="token property">height</span><span class="token punctuation">:</span> 100dvh<span class="token punctuation">;</span> <span class="token punctuation">}</span> <span class="token comment">/* 不支持的浏览器忽略第二行 */</span>
<span class="token comment">/* JS 兜底 */</span>
<span class="token comment">/* document.documentElement.style.setProperty(&#39;--vh&#39;, window.innerHeight + &#39;px&#39;) */</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>svh</code> 和 <code>dvh</code> 该用哪个？答：希望高度随地址栏实时变化用 <code>dvh</code>；希望绝对不出现超出可视区、宁可略矮用 <code>svh</code>。</li><li>陷阱：只答&quot;用 <code>100%</code> 代替&quot;，但 <code>100%</code> 需要父级有确定高度，链式写错照样不生效。</li><li>陷阱：忽略键盘弹起时的视口变化，输入框被键盘遮住，这时要用 <code>visualViewport</code> 或 <code>scrollIntoView</code> 配合处理。</li></ul><h3 id="q43-display-none、visibility-hidden、opacity-0-有什么区别" tabindex="-1"><a class="header-anchor" href="#q43-display-none、visibility-hidden、opacity-0-有什么区别" aria-hidden="true">#</a> Q43 display: none、visibility: hidden、opacity: 0 有什么区别？</h3><p><strong>考察点</strong>：隐藏元素的三种方式辨析，考占位、事件、动画与可访问性四个维度。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>display: none</code> 彻底不渲染、不占位、不可交互、无法过渡；<code>visibility: hidden</code> 不渲染但<strong>保留占位</strong>、不可交互、可以过渡（可设延迟）；<code>opacity: 0</code> 正常渲染并占位、<strong>仍可点击</strong>、可平滑过渡。</p></blockquote><table><thead><tr><th>方式</th><th>是否占位</th><th>是否可交互</th><th>子元素能否显示</th><th>过渡动画</th><th>触发回流</th></tr></thead><tbody><tr><td><code>display: none</code></td><td>否</td><td>否</td><td>不能</td><td>不支持</td><td>是（重排）</td></tr><tr><td><code>visibility: hidden</code></td><td>是</td><td>否</td><td>可以（子级设 <code>visible</code>）</td><td>支持</td><td>否（重绘）</td></tr><tr><td><code>opacity: 0</code></td><td>是</td><td>是（需配 <code>pointer-events: none</code>）</td><td>不能（受父级影响）</td><td>支持</td><td>否（重绘）</td></tr></tbody></table><ol><li><code>visibility</code> 可继承且子元素能独立覆盖，所以父级隐藏时可以让某个子元素仍然可见，这是它独一无二的能力；它还能做 <code>transition: visibility 0s .3s</code> 的延迟隐藏。</li><li><code>opacity: 0</code> 常用于淡入淡出，但要记得加 <code>pointer-events: none</code>，否则透明元素会拦截点击；且它创建层叠上下文，可能影响 <code>z-index</code> 表现。</li><li>可访问性差异：<code>display: none</code> 与 <code>visibility: hidden</code> 的内容不会被屏幕阅读器朗读，<code>opacity: 0</code> 的内容仍会被朗读，可能造成&quot;看着空白但能听到内容&quot;的错乱。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：只想让元素视觉上消失、布局不动、又要能过渡，用哪个？答：<code>opacity: 0</code> 加 <code>pointer-events: none</code>，或 <code>visibility: hidden</code> 配延迟过渡。</li><li>陷阱：把 <code>visibility: hidden</code> 说成会触发重排。它占位与几何都不变，只触发重绘；只有 <code>opacity</code>、<code>transform</code> 这类属性才可能连重绘都省掉、只做合成。</li><li>陷阱：用 <code>display: none</code> 做动画，<code>transition</code> 完全无效，因为元素不进渲染树，必须配合 <code>@keyframes</code> 或先显示再切类名。</li></ul><h3 id="q44-为什么-height-100-有时不生效" tabindex="-1"><a class="header-anchor" href="#q44-为什么-height-100-有时不生效" aria-hidden="true">#</a> Q44 为什么 height: 100% 有时不生效？</h3><p><strong>考察点</strong>：百分比高度解析条件是基础硬知识，也是很多&quot;撑不满屏幕&quot;问题的根因。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：百分比高度必须能解析出参照值，也就是父元素要有<strong>确定的</strong>高度；父元素 <code>height: auto</code> 时百分比高度被当作 <code>auto</code> 处理，于是不生效。</p></blockquote><ol><li>规则：<code>height</code> 的百分比相对包含块的高度计算（<code>padding</code> 百分比相对宽度）。包含块高度由内容决定（<code>auto</code>）时，就没有确定的参照值，声明失效。</li><li>链式生效写法：从根一路给到目标元素，<code>html, body { height: 100% }</code>，再逐层 <code>height: 100%</code>。只要中间断一层，后面全部失效。</li><li>更好的替代：全屏布局直接用视口单位 <code>100dvh</code> / <code>100vh</code>，或用 flex 让子元素拉伸（父级 <code>display: flex</code>、子项 <code>flex: 1</code>），或 Grid 的 <code>1fr</code> 行轨道。</li><li>绝对定位元素的特例：父级是定位祖先时，绝对定位子元素的百分比高度参照其 padding box，所以只要有定位祖先且有确定高度就能生效。</li></ol><div class="language-css line-numbers-mode" data-ext="css"><pre class="language-css"><code><span class="token selector">html, body</span> <span class="token punctuation">{</span> <span class="token property">height</span><span class="token punctuation">:</span> 100%<span class="token punctuation">;</span> <span class="token punctuation">}</span>              <span class="token comment">/* 链式方案，缺一不可 */</span>
<span class="token selector">.app</span> <span class="token punctuation">{</span> <span class="token property">display</span><span class="token punctuation">:</span> flex<span class="token punctuation">;</span> <span class="token property">flex-direction</span><span class="token punctuation">:</span> column<span class="token punctuation">;</span> <span class="token property">height</span><span class="token punctuation">:</span> 100%<span class="token punctuation">;</span> <span class="token punctuation">}</span>
<span class="token selector">.app main</span> <span class="token punctuation">{</span> <span class="token property">flex</span><span class="token punctuation">:</span> 1<span class="token punctuation">;</span> <span class="token property">min-height</span><span class="token punctuation">:</span> 0<span class="token punctuation">;</span> <span class="token punctuation">}</span>     <span class="token comment">/* 内容区自动填满剩余高度 */</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>min-height: 100%</code> 也失效怎么办？答：同样依赖父级确定高度；若只是想让内容不足时页面也撑满，用 <code>min-height: 100dvh</code> 或 <code>body { min-height: 100vh }</code> 更直接。</li><li>陷阱：只给目标元素写 <code>height: 100%</code> 而父级没有高度，然后怀疑是浏览器 bug。</li><li>陷阱：用 flex 时忘了 <code>min-height: 0</code>，内容区被内部长内容撑高而不出现内部滚动。</li></ul><h3 id="q45-margin-负值有什么用-会产生什么影响" tabindex="-1"><a class="header-anchor" href="#q45-margin-负值有什么用-会产生什么影响" aria-hidden="true">#</a> Q45 margin 负值有什么用？会产生什么影响？</h3><p><strong>考察点</strong>：负 margin 是很多经典布局的实现基础，考理解是否到位。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：负 <code>margin</code> 让元素在布局计算中&quot;占用更小的空间&quot;，从而向外移动或与相邻元素重叠，是圣杯/双飞翼、抵消多余间距的常用手段，但它不改变元素自身尺寸，也不影响文档流顺序。</p></blockquote><ol><li>四个方向的语义：<code>margin-left</code> 为负会让元素向左移动（或使右侧内容左移）；<code>margin-top</code> 为负让元素上移并与上方元素重叠；<code>margin-right</code> 为负会减少元素在行内占据的右侧空间。</li><li>经典用法一：<strong>负 margin 三栏布局</strong>，把浮动侧栏从下一行拉回上一行（见 Q24）。</li><li>经典用法二：<strong>抵消列表末位或行末的多余间距</strong>，例如卡片列表用 <code>margin-right: -16px</code> 包一层、子项 <code>margin-right: 16px</code>，让最右侧间距被吃掉；有了 <code>gap</code> 之后这类技巧基本可以退休。</li><li>经典用法三：<strong>视觉重叠与梯形/斜切装饰</strong>，例如轮播图相邻项轻微重叠、卡片叠压效果。风险是负 <code>margin</code> 会导致父元素高度计算异常、滚动条与溢出问题，且负值过大时元素会被裁剪或覆盖到不该覆盖的位置。</li></ol><div class="language-css line-numbers-mode" data-ext="css"><pre class="language-css"><code><span class="token comment">/* 抵消末尾间距的旧写法 */</span>
<span class="token selector">.list</span> <span class="token punctuation">{</span> <span class="token property">display</span><span class="token punctuation">:</span> flex<span class="token punctuation">;</span> <span class="token property">flex-wrap</span><span class="token punctuation">:</span> wrap<span class="token punctuation">;</span> <span class="token property">margin-right</span><span class="token punctuation">:</span> -16px<span class="token punctuation">;</span> <span class="token punctuation">}</span>
<span class="token selector">.list &gt; *</span> <span class="token punctuation">{</span> <span class="token property">margin-right</span><span class="token punctuation">:</span> 16px<span class="token punctuation">;</span> <span class="token punctuation">}</span>
<span class="token comment">/* 现代写法：.list { display: flex; flex-wrap: wrap; gap: 16px; } */</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：负 <code>margin</code> 会影响元素自身宽度吗？答：不会。它只改变元素在布局中的位置与所占空间，元素盒子尺寸不变。</li><li>陷阱：用负 <code>margin</code> 做布局后，父元素出现高度塌陷或页面无法滚动到底，排查时看是否缺少 <code>overflow: hidden</code> 或应该改用 flex / grid。</li><li>陷阱：把负 <code>margin</code> 与 <code>position: relative</code> 混用做&quot;位移&quot;，两者都会创建层叠上下文或引发重叠，优先用 <code>transform: translate</code> 做纯视觉位移。</li></ul><h2 id="本章小结" tabindex="-1"><a class="header-anchor" href="#本章小结" aria-hidden="true">#</a> 本章小结</h2><ul><li>盒模型用 <code>box-sizing: border-box</code> 统一，<code>width</code> 就包含了 padding 与 border，栅格不再被撑破。</li><li>外边距合并只发生在块级元素的垂直方向，三种情形都靠创建 BFC、加 padding/border 或改用 flex/grid 破解。</li><li>BFC 的三条实用价值：清浮动、阻止 margin 合并、实现不被浮动覆盖的自适应两栏。</li><li>包含块决定百分比与偏移的参照：<code>absolute</code> 看最近的定位祖先 padding box，<code>fixed</code> 看视口，但 <code>transform</code> 会改写这两条规则。</li><li><code>z-index</code> 只对定位元素或已创建层叠上下文的元素生效，子元素的层级永远出不了父级层叠上下文。</li><li>Flex 管一维、Grid 管二维；<code>flex: 1</code> 是 <code>1 1 0%</code>，配 <code>min-width: 0</code> 才能解决弹性项目溢出。</li><li>居中优先用 flex/grid，需要精确控制时用绝对定位 + <code>transform</code> 或 <code>margin: auto</code>，绝对定位 + <code>margin: auto</code> 依赖&quot;过约束&quot;才有剩余空间可分配。</li><li>长度单位按用途选：<code>rem</code> 做体系、<code>px</code> 做细节、<code>dvh</code> 替代 <code>100vh</code>，响应式尺寸优先 <code>clamp()</code> 与 <code>minmax()</code>。</li><li>能继承的是文字排版类属性，布局类属性不继承；优先用低权重选择器与 <code>:where()</code>，把 <code>!important</code> 留到最后手段。</li></ul>`,356);function d(i,p){return e(),n("div",null,[t,s(" COUNT: 45 ")])}const r=o(a,[["render",d],["__file","08-css-layout.html.vue"]]);export{r as default};
